insert into public.species (id,name_zh,name_sci,wikidata_id,photo_url,photo_credit,photo_license,photo_page,description) values (36,'翻白葉樹','Pterospermum heterophyllum',NULL,'/photos/species/35.jpg','Wikimedia Commons','Public domain','https://commons.wikimedia.org/wiki/File:A_systematic_catalogue_of_the_flowering_plants_and_ferns_indigenous_to_or_growing_wild_in_Ceylon_(IA_cu31924000414510).pdf','常綠喬木。葉革質，二型，生於幼樹或萌蘗枝上的葉盾形， 直徑約1 5 cm，掌狀3 - 5裂， 上面幾無毛，下面密被褐色星狀短柔毛；葉柄長約1 2 cm， 被毛， 生於成長樹上的葉長圓形至卵狀長圓形，頂端漸尖或鈍，基部斜圓形或斜心形， 長7-15cm，寬3-10cm，下面密被黃褐色短柔毛；葉柄長1-2cm。花單生或2-4朵組成腋生的聚傘花序；萼裂片條形，長約2.5cm，兩面均被柔毛；花瓣白色，倒披針形，與萼片等長；雌雄蕊柄長2.5cm，雄蕊15枚，每3個組成一組；子房卵圓形，被毛。蒴果木質，長圓狀卵形，長4-6cm，寬2-2.5cm，被黃褐色絨毛 ; 種子頂端具膜質翅。花期6-7月 ; 果期8-12月。');
