('605',9,21,'嘉模堂區','三級',145,12.0,'一般',22.156477,113.559294,'official','605','T0000205','436ee59c-85d2-4532-a754-45846ce25133',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','氹仔區飛能便度街','/photos/trees/605.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1029073.jpg',1,145,12.0,'一般','三級'),
('614',9,8,'嘉模堂區','三級',145,11.0,'一般',22.152248,113.555199,'official','614','T0000236','7dc9e369-f9ee-495b-b7ea-6907275daa7d',8.1,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','氹仔區巴波沙總督前地','/photos/trees/614.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004815.jpg',1,145,11.0,'一般','三級'),
('664',10,93,'路氹填海區','三級',145,7.01,'一般',22.13993149,113.5523004,'official','664','T0000382','06665e69-c033-4ca3-899c-8ec4ecc87a01',NULL,NULL,NULL,'落葉大喬木，高可達25m以上；樹幹幼時有粗刺。掌狀複葉互生；葉柄稍長於小葉；小葉5-7片，長圓形至長圓狀披針形長10-20cm，寬3.5-7cm，頂端漸尖，基部闊楔形或漸窄，全緣，兩面無毛；小葉柄長約1.5-4cm。花紅色或橙紅色，直徑10-12cm，單生或聚生於近枝頂的葉腋；花萼杯狀，長2-4.5cm，內面被絹毛，3-5裂，裂片半圓形；花瓣帶肉質倒卵狀長圓形，長8-10cm，寬3-4cm，兩面多少有星狀細毛；雄蕊管短，花絲多數，外輪集成5組，與花瓣對生。蒴果長圓形，長10-15cm；種子藏於白色綿毛中。','路氹填海區海濱圓形地','/photos/trees/664.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004962.jpg',1,145,7.01,'一般','三級'),
('877',16,47,'風順堂區','三級',145,24.0,'健康',22.192238,113.5381973,'official','877','T0000148','786b0abc-5c9b-491e-a7ec-0e553f2bc864',NULL,210.0,659.7,'常綠喬木；各部無毛，老樹常具鏽褐色氣根。葉薄革質，狹橢圓形，長4-8cm，寬3-4cm，全緣；托葉小，披針形。雌雄同株，榕果成對腋生或生於已落葉枝葉腋，熟時黃或微紅色，扁球形，徑6-8mm，無總柄，基生苞片3枚，廣卵形，宿存；榕果內花間有少許短剛毛，雄花無柄或具柄，散生內壁，花絲與花藥等長；雌花和癭花相似，花被片3枚，廣卵形，花柱近側生，柱頭短，棒形。瘦果卵圓形。花果期5-12月。','澳門區岡頂前地','/photos/trees/877.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004720.jpg',1,145,24.0,'健康','三級'),
('494',10,65,'花王堂區','三級',145,24.0,'健康',22.199369,113.541279,'official','494','T0000460','d62e2e3f-d681-40c9-8a97-753d26095e62',NULL,92.0,289.0,'落葉大喬木，高可達25m以上；樹幹幼時有粗刺。掌狀複葉互生；葉柄稍長於小葉；小葉5-7片，長圓形至長圓狀披針形長10-20cm，寬3.5-7cm，頂端漸尖，基部闊楔形或漸窄，全緣，兩面無毛；小葉柄長約1.5-4cm。花紅色或橙紅色，直徑10-12cm，單生或聚生於近枝頂的葉腋；花萼杯狀，長2-4.5cm，內面被絹毛，3-5裂，裂片半圓形；花瓣帶肉質倒卵狀長圓形，長8-10cm，寬3-4cm，兩面多少有星狀細毛；雄蕊管短，花絲多數，外輪集成5組，與花瓣對生。蒴果長圓形，長10-15cm；種子藏於白色綿毛中。','澳門區澳門基督教聖堂及墳場','/photos/trees/494.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005038.jpg',1,145,24.0,'健康','三級'),
('910',9,96,'聖方濟各堂區','三級',145,24.0,'健康',22.13203214,113.5889447,'official','910','T0000570','555f0602-ace7-4021-9152-477eb044ba96',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區九澳聖母馬路','/photos/trees/910.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005152.jpg',1,145,24.0,'健康','三級'),
('911',9,96,'聖方濟各堂區','三級',145,24.0,'健康',22.131926,113.58905,'official','911','T0000554','074f3328-f3aa-4323-9202-fe5f0bf1db4f',NULL,203.0,637.7,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區九澳聖母馬路','/photos/trees/911.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1029849.jpg',1,145,24.0,'健康','三級'),
('445',16,68,'花王堂區','三級',145,18.0,'健康',22.19928,113.539261,'official','445','T0000376','e26874ce-4542-4b08-acef-cc4171b7e7c2',NULL,NULL,NULL,'常綠喬木；各部無毛，老樹常具鏽褐色氣根。葉薄革質，狹橢圓形，長4-8cm，寬3-4cm，全緣；托葉小，披針形。雌雄同株，榕果成對腋生或生於已落葉枝葉腋，熟時黃或微紅色，扁球形，徑6-8mm，無總柄，基生苞片3枚，廣卵形，宿存；榕果內花間有少許短剛毛，雄花無柄或具柄，散生內壁，花絲與花藥等長；雌花和癭花相似，花被片3枚，廣卵形，花柱近側生，柱頭短，棒形。瘦果卵圓形。花果期5-12月。','澳門區白鴿巢公園','/photos/trees/445.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004956.jpg',1,145,18.0,'健康','三級'),
('810',17,61,'望德堂區','三級',145,18.0,'健康',22.19541249,113.5502747,'official','810','T0000498','234514ec-748e-4af6-a7e0-3cbbfec39da2',NULL,148.0,465.0,'常綠大喬木；高10-20(-30)m，胸徑達1-3m，樹冠大；具樟腦香氣；小枝無毛。葉薄革質，互生，卵狀橢圓形或長卵形，長6-12cm，寬2.5-6.5cm，頂端急尖，基部寬楔形至近圓形，邊緣多少波狀，葉面深綠色或黃綠色，有光澤，背面無毛或初時微被短柔毛；離基三出脈，側脈每邊2-5條，中脈在葉兩面均明顯，側脈在葉面上稍凸起，背面脈腋具明顯腺窩，窩內有短柔毛；葉柄長2-3cm。花多朵，排成圓錐花序狀的聚傘花序，花序長3.5-7cm，無毛或初時微被短柔毛；花黃白色或黃綠色，長約3mm，花被筒漏斗狀，花被裂片橢圓形，長約2mm，外面初時微被短柔毛，後脫落，內面密被短柔毛；子房近圓形，花柱短，柱頭頭狀。果近球形或卵球形，直徑6-8mm，熟時紫黑色，基部爲增大成淺杯狀或碟狀的果托所承托，果托邊緣全緣。花期4-5月；果期8-11月。','澳門區海邊馬路','/photos/trees/810.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005080.jpg',1,145,18.0,'健康','三級'),
('47',17,126,'聖方濟各堂區','三級',145,17.0,'健康',22.123003,113.57063,'official','47','T0000585','2bf40b16-1736-4a6d-9a09-97731508a2ba',NULL,NULL,NULL,'常綠大喬木；高10-20(-30)m，胸徑達1-3m，樹冠大；具樟腦香氣；小枝無毛。葉薄革質，互生，卵狀橢圓形或長卵形，長6-12cm，寬2.5-6.5cm，頂端急尖，基部寬楔形至近圓形，邊緣多少波狀，葉面深綠色或黃綠色，有光澤，背面無毛或初時微被短柔毛；離基三出脈，側脈每邊2-5條，中脈在葉兩面均明顯，側脈在葉面上稍凸起，背面脈腋具明顯腺窩，窩內有短柔毛；葉柄長2-3cm。花多朵，排成圓錐花序狀的聚傘花序，花序長3.5-7cm，無毛或初時微被短柔毛；花黃白色或黃綠色，長約3mm，花被筒漏斗狀，花被裂片橢圓形，長約2mm，外面初時微被短柔毛，後脫落，內面密被短柔毛；子房近圓形，花柱短，柱頭頭狀。果近球形或卵球形，直徑6-8mm，熟時紫黑色，基部爲增大成淺杯狀或碟狀的果托所承托，果托邊緣全緣。花期4-5月；果期8-11月。','路環區黑沙海灘公園','/photos/trees/47.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005172.jpg',1,145,17.0,'健康','三級'),
('484',51,68,'花王堂區','三級',145,16.0,'健康',22.200506,113.540754,'official','484','T0000317','3bad0921-f80b-4762-aca1-270f5bb8b8c0',NULL,142.0,446.1,'喬木；幼枝綠色，被微柔毛。葉厚革質，寬卵形至寬卵狀橢圓形，長10-19cm，寬8-11cm，全緣，兩面無毛；托葉厚革質，長2-3cm，被灰色絲毛。雌雄同株，榕果成對腋生，橢圓狀卵圓形，徑1.7-2.8cm，無總柄，幼時包於早落風帽狀苞片內，熟時紅或帶黃色，基生苞片短寬，脫落後環狀；雄花散生榕果內壁，花被片4片，雄蕊1枚；雌花無梗，花被片與癭花同數，花柱長，柱頭棒狀，子房基部具紅斑。瘦果表面具小瘤。花果期3-10月。','澳門區白鴿巢公園','/photos/trees/484.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004895.jpg',1,145,16.0,'健康','三級'),
('365',9,23,'風順堂區','三級',145,15.0,'健康',22.187178,113.53487,'official','365','T0000521','32981e24-822d-4e8c-924e-8aecb34cbece',NULL,204.0,640.9,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區主教山小堂','/photos/trees/365.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005103.jpg',1,145,15.0,'健康','三級'),
('298',51,37,'望德堂區','三級',145,15.0,'健康',22.195365,113.550813,'official','298','T0034377','a3bf5778-9008-4fb9-b714-ae6c82a657f4',NULL,167.0,524.6,'喬木；幼枝綠色，被微柔毛。葉厚革質，寬卵形至寬卵狀橢圓形，長10-19cm，寬8-11cm，全緣，兩面無毛；托葉厚革質，長2-3cm，被灰色絲毛。雌雄同株，榕果成對腋生，橢圓狀卵圓形，徑1.7-2.8cm，無總柄，幼時包於早落風帽狀苞片內，熟時紅或帶黃色，基生苞片短寬，脫落後環狀；雄花散生榕果內壁，花被片4片，雄蕊1枚；雌花無梗，花被片與癭花同數，花柱長，柱頭棒狀，子房基部具紅斑。瘦果表面具小瘤。花果期3-10月。','澳門區啟智學校','/photos/trees/298.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/2704355.jpg',1,145,15.0,'健康','三級'),
('947',21,11,'嘉模堂區','三級',145,13.0,'健康',22.161939,113.559132,'official','947','T0034417','aa45069e-f350-41ca-b4d0-a9800242232f',NULL,88.95,279.4,'喬木，高達15m；嫩枝圓形，乾後灰白色。葉革質，寬或狹橢圓形，長6-12cm，寬3.5-7cm，頂端圓或鈍，有短尖頭，基部寬楔形，稀近圓形，葉面乾後褐色或黑褐色，背面色稍淺，具密小腺點；側脈多而密；葉柄長1-2cm。花3-5朵排成聚傘花序，並再組成圓錐花序狀的聚傘花序，此花序長可達11cm；花梗極短，花萼筒短小，漏斗形，花萼齒小；花瓣4，小，白色；雄蕊短。漿果，卵球形或壺形，直徑1-2cm，熟時有宿存萼齒；種子1枚。花期2-3月。','氹仔區徐日昇寅公馬路','/photos/trees/947.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/2722893.jpg',1,145,13.0,'健康','三級'),
('652',9,94,'路氹填海區','三級',145,9.01,'健康',22.13979126,113.5536093,'official','652','T0000401','80153125-2c1b-4a98-90a3-43619d670ff6',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路氹填海區蓮花路','/photos/trees/652.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004981.jpg',1,145,9.01,'健康','三級'),
('429',34,68,'花王堂區','三級',145,9.0,'健康',22.201507,113.540053,'official','429','T0000297','48f28601-bbfe-11c8-8000-65df20910223',NULL,57.0,179.1,'常綠喬木；小枝密被黑色軟毛或無；頂芽卵圓形，芽鱗頂端長漸尖。葉螺旋狀着生，革質，線狀披針形，微彎，長7-15cm，寬0.7-1cm，上部微漸窄，頂端尖，基部楔形，上面深綠色；中脈顯著隆起，下面灰綠色，被白粉。雄球花穗狀，常2-5簇生，長3-5cm；雌球花單生稀成對，具梗。種子卵圓形或近球形，徑約1cm，成熟時假種皮紫黑色，被白粉，肉質種托柱狀橢圓形，紅或紫紅色。','澳門區白鴿巢公園','/photos/trees/429.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004876.jpg',1,145,9.0,'健康','三級'),
('552',9,3,'嘉模堂區','三級',145,13.0,'瀕危',22.15401539,113.5587112,'official','552','T0000018','e5c68e40-89c0-43ce-a90c-9eab44562c31',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','氹仔區嘉模斜巷','/photos/trees/552.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004545.jpg',1,145,13.0,'瀕危','三級'),
('975',15,43,'風順堂區','三級',140,14.0,'一般',22.18289707,113.5304409,'official','975','T0000023','d9c770ab-35e2-4be0-843b-a1b05d73773e',NULL,NULL,NULL,'落葉或半常綠小喬木，高5-15m；小枝幼時被毛。葉近革質；葉柄長3-5mm，被短柔毛；葉片橢圓形至卵圓形或倒卵形，長2-5cm，寬0.8-2.2cm，頂端漸尖，或微鈍，基部近圓形，不對稱，邊緣有鋸齒上面無毛，下面幼時被細毛。花簇生於葉腋間，秋季開放。翅果橢圓形長10-12mm，頂端凹缺。','澳門區媽閣上街','/photos/trees/975.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1058395.jpg',1,140,14.0,'一般','三級'),
('231',36,88,'花地瑪堂區','三級',135,32.0,'一般',22.212568,113.537601,'official','231','T0000424','90b89076-080c-4aca-a0f5-5cd958ecc02b',NULL,64.3,202.0,'常綠喬木。葉革質，二型，生於幼樹或萌蘗枝上的葉盾形， 直徑約1 5 cm，掌狀3 - 5裂， 上面幾無毛，下面密被褐色星狀短柔毛；葉柄長約1 2 cm， 被毛， 生於成長樹上的葉長圓形至卵狀長圓形，頂端漸尖或鈍，基部斜圓形或斜心形， 長7-15cm，寬3-10cm，下面密被黃褐色短柔毛；葉柄長1-2cm。花單生或2-4朵組成腋生的聚傘花序；萼裂片條形，長約2.5cm，兩面均被柔毛；花瓣白色，倒披針形，與萼片等長；雌雄蕊柄長2.5cm，雄蕊15枚，每3個組成一組；子房卵圓形，被毛。蒴果木質，長圓狀卵形，長4-6cm，寬2-2.5cm，被黃褐色絨毛 ; 種子頂端具膜質翅。花期6-7月 ; 果期8-12月。','澳門區青洲山','/photos/trees/231.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005003.jpg',1,135,32.0,'一般','三級'),
('472',4,68,'花王堂區','三級',135,24.0,'一般',22.198418,113.539816,'official','472','T0000454','611f1568-f173-4093-b8e4-b65eb0877fd9',NULL,124.0,389.6,'常綠喬木，高達18m；樹皮灰色或灰褐色；芽鱗、小枝密被鏽色短柔毛。葉薄革質，互生，寬卵形、倒卵形至卵狀長圓形，長8-20cm，寬4-12cm，頂端鈍或圓，偶有急尖，基部圓或急尖，幼葉上面沿中脈有鏽色短柔毛，老時漸脫落變無毛，背面密被鏽色短柔毛；羽狀脈，側脈每邊8-12條，有近平行的橫脈相聯，中脈、側脈在葉面下陷；葉柄長1-3cm，密被鏽色短柔毛。花4-6朵或更多，排成傘形花序狀的聚傘花序，花序梗極短；苞片膜質；花梗有鏽色柔毛；能育雄蕊9枚，花絲纖細，有柔毛。果長卵形，直徑5mm，果托淺碟狀，果梗短。花期11月至翌年6月；果期6-7月。','澳門區白鴿巢公園','/photos/trees/472.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/14587.jpg',1,135,24.0,'一般','三級'),
('906',10,87,'望德堂區','三級',135,24.0,'一般',22.19851482002601,113.54340228013281,'official','906','T0034381','59b52b88-7688-45df-9fd0-9b20d5db5bd5',NULL,119.0,373.8,'落葉大喬木，高可達25m以上；樹幹幼時有粗刺。掌狀複葉互生；葉柄稍長於小葉；小葉5-7片，長圓形至長圓狀披針形長10-20cm，寬3.5-7cm，頂端漸尖，基部闊楔形或漸窄，全緣，兩面無毛；小葉柄長約1.5-4cm。花紅色或橙紅色，直徑10-12cm，單生或聚生於近枝頂的葉腋；花萼杯狀，長2-4.5cm，內面被絹毛，3-5裂，裂片半圓形；花瓣帶肉質倒卵狀長圓形，長8-10cm，寬3-4cm，兩面多少有星狀細毛；雄蕊管短，花絲多數，外輪集成5組，與花瓣對生。蒴果長圓形，長10-15cm；種子藏於白色綿毛中。','澳門區鏡湖醫院','/photos/trees/906.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1834568.jpg',1,135,24.0,'一般','三級'),
('471',4,68,'花王堂區','三級',135,23.0,'一般',22.202481,113.540286,'official','471','T0000462','1cd8cf8b-0c7b-451f-acac-483a600ee8bc',NULL,74.0,232.5,'常綠喬木，高達18m；樹皮灰色或灰褐色；芽鱗、小枝密被鏽色短柔毛。葉薄革質，互生，寬卵形、倒卵形至卵狀長圓形，長8-20cm，寬4-12cm，頂端鈍或圓，偶有急尖，基部圓或急尖，幼葉上面沿中脈有鏽色短柔毛，老時漸脫落變無毛，背面密被鏽色短柔毛；羽狀脈，側脈每邊8-12條，有近平行的橫脈相聯，中脈、側脈在葉面下陷；葉柄長1-3cm，密被鏽色短柔毛。花4-6朵或更多，排成傘形花序狀的聚傘花序，花序梗極短；苞片膜質；花梗有鏽色柔毛；能育雄蕊9枚，花絲纖細，有柔毛。果長卵形，直徑5mm，果托淺碟狀，果梗短。花期11月至翌年6月；果期6-7月。','澳門區白鴿巢公園',NULL,NULL,1,135,23.0,'一般','三級'),
('436',9,68,'花王堂區','三級',135,22.0,'一般',22.199216,113.540223,'official','436','T0000301','38730601-bcf9-11c8-8000-5708262460c3',NULL,162.0,508.9,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區白鴿巢公園','/photos/trees/436.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004880.jpg',1,135,22.0,'一般','三級'),
('232',36,88,'花地瑪堂區','三級',135,22.0,'一般',22.211296,113.537658,'official','232','T0000430','29b6ff5b-7ffe-42dd-87ba-859f41202e56',NULL,46.8,147.0,'常綠喬木。葉革質，二型，生於幼樹或萌蘗枝上的葉盾形， 直徑約1 5 cm，掌狀3 - 5裂， 上面幾無毛，下面密被褐色星狀短柔毛；葉柄長約1 2 cm， 被毛， 生於成長樹上的葉長圓形至卵狀長圓形，頂端漸尖或鈍，基部斜圓形或斜心形， 長7-15cm，寬3-10cm，下面密被黃褐色短柔毛；葉柄長1-2cm。花單生或2-4朵組成腋生的聚傘花序；萼裂片條形，長約2.5cm，兩面均被柔毛；花瓣白色，倒披針形，與萼片等長；雌雄蕊柄長2.5cm，雄蕊15枚，每3個組成一組；子房卵圓形，被毛。蒴果木質，長圓狀卵形，長4-6cm，寬2-2.5cm，被黃褐色絨毛 ; 種子頂端具膜質翅。花期6-7月 ; 果期8-12月。','澳門區青洲山','/photos/trees/232.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005009.jpg',1,135,22.0,'一般','三級'),
('441',9,68,'花王堂區','三級',135,21.0,'一般',22.202334,113.538324,'official','441','T0000307','828b0001-bf22-11c8-8000-5708262460c3',NULL,173.0,543.5,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區白鴿巢公園','/photos/trees/441.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004886.jpg',1,135,21.0,'一般','三級'),
('835',46,36,'大堂區','三級',135,21.0,'一般',22.192451,113.544941,'official','835','T0000339','61980401-5f73-11c9-8000-3b014a847002',NULL,87.0,273.3,'落葉喬木。二回羽狀複葉有羽片2-4對，葉軸上有腺體；小葉4-8對，長橢圓形，長2-4.5cm，寬1.3-2cm，頂端圓鈍或微凹，中脈略偏於上邊緣。頭狀花序直徑3-4cm，1至數個生於葉腋，總花梗長7-9mm；花冠黃綠色，芳香，長7-8mm。莢果帶狀，長15-28cm，寬2.5-4.5cm，扁平，麥桿色，常宿存於樹上經久不落。花期 5-9月；果期 10月至翌年5月。','澳門區加思欄花園','/photos/trees/835.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004915.jpg',1,135,21.0,'一般','三級'),
('529',37,69,'望德堂區','三級',135,20.0,'一般',22.199885,113.547852,'official','529','T0000286','d7d87b00-a465-11c8-8000-e9800050cec3',NULL,76.0,238.8,'常綠喬木。樹皮灰褐色，小枝褐色。葉薄革質，常集生枝頂，葉形及大小變化較大，常爲長圓形或長圓狀披針形，長12-30cm，寬3.5-6.5cm，邊緣皺波狀；葉柄長2-6cm，基部膨大。圓錐花序長20-35cm，多花密集，被灰黃色微柔毛；花小，雜性，錐花序長20-35cm，多花密集，被灰黃色微柔毛；花小，雜性，膨大，肉質，5淺裂；雄蕊僅1個發育；子房斜卵形，花柱近頂生。核果大，壓扁，成熟時黃色，中果皮肉質，肥厚，鮮黃色，果核堅硬。花期春季；果期夏季。','澳門區盧廉若公園','/photos/trees/529.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004865.jpg',1,135,20.0,'一般','三級'),
('511',45,68,'花王堂區','三級',135,19.0,'一般',22.200974,113.541728,'official','511','T0000042','5ba1c701-bbcf-4aa6-a8cd-b30d58ecdc74',NULL,71.0,223.1,'喬木，高約10m；樹皮灰色，有皮孔，嫩枝有縱棱，疏被短柔毛。羽狀複葉；無腺體，葉柄及葉軸被微柔毛；小葉6-10對，長圓形或長圓狀橢圓形，革質，長3-6.5cm，寬1.5-2.5cm，頂端圓鈍，常微凹，有0.5mm長的小尖頭，基部圓形，上面光滑無毛，下面粉白色。總狀花序生於枝條頂端的葉腋，並排成傘房花序狀；萼片近圓形，被細毛；花瓣黃色，倒闊卵形，長12-14mm；雄蕊10枚，7枚能育，3枚退化不育。莢果扁平，長15-30cm，寬1-1.5cm，邊緣加厚，被柔毛；種子10-20顆。花期10-11月；果期12月至翌年1月。','澳門區白鴿巢前地','/photos/trees/511.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004604.jpg',1,135,19.0,'一般','三級'),
('249',21,88,'花地瑪堂區','三級',135,19.0,'一般',22.211152,113.536856,'official','249','T0000438','33db0e52-579c-4f6e-a1aa-ea449f42b7b1',NULL,66.8,210.0,'喬木，高達15m；嫩枝圓形，乾後灰白色。葉革質，寬或狹橢圓形，長6-12cm，寬3.5-7cm，頂端圓或鈍，有短尖頭，基部寬楔形，稀近圓形，葉面乾後褐色或黑褐色，背面色稍淺，具密小腺點；側脈多而密；葉柄長1-2cm。花3-5朵排成聚傘花序，並再組成圓錐花序狀的聚傘花序，此花序長可達11cm；花梗極短，花萼筒短小，漏斗形，花萼齒小；花瓣4，小，白色；雄蕊短。漿果，卵球形或壺形，直徑1-2cm，熟時有宿存萼齒；種子1枚。花期2-3月。','澳門區青洲山','/photos/trees/249.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005017.jpg',1,135,19.0,'一般','三級'),
('913',16,105,'聖方濟各堂區','三級',135,18.0,'一般',22.11839195,113.5523141,'official','913','T0000572','d9ab222d-61e9-473f-a4c2-47a8b2337627',10.0,NULL,NULL,'常綠喬木；各部無毛，老樹常具鏽褐色氣根。葉薄革質，狹橢圓形，長4-8cm，寬3-4cm，全緣；托葉小，披針形。雌雄同株，榕果成對腋生或生於已落葉枝葉腋，熟時黃或微紅色，扁球形，徑6-8mm，無總柄，基生苞片3枚，廣卵形，宿存；榕果內花間有少許短剛毛，雄花無柄或具柄，散生內壁，花絲與花藥等長；雌花和癭花相似，花被片3枚，廣卵形，花柱近側生，柱頭短，棒形。瘦果卵圓形。花果期5-12月。','路環區田畔街','/photos/trees/913.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005154.jpg',1,135,18.0,'一般','三級'),
('427',9,68,'花王堂區','三級',135,17.0,'一般',22.199605,113.537952,'official','427','T0000299','080e6781-bc26-11c8-8000-5708262460c3',NULL,270.0,848.2,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區白鴿巢公園','/photos/trees/427.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004878.jpg',1,135,17.0,'一般','三級'),
('470',16,68,'花王堂區','三級',135,17.0,'一般',22.199867,113.537085,'official','470','T0000450','ba954149-cfe3-4155-acf1-bbee154ad62a',NULL,96.0,301.6,'常綠喬木；各部無毛，老樹常具鏽褐色氣根。葉薄革質，狹橢圓形，長4-8cm，寬3-4cm，全緣；托葉小，披針形。雌雄同株，榕果成對腋生或生於已落葉枝葉腋，熟時黃或微紅色，扁球形，徑6-8mm，無總柄，基生苞片3枚，廣卵形，宿存；榕果內花間有少許短剛毛，雄花無柄或具柄，散生內壁，花絲與花藥等長；雌花和癭花相似，花被片3枚，廣卵形，花柱近側生，柱頭短，棒形。瘦果卵圓形。花果期5-12月。','澳門區白鴿巢公園','/photos/trees/470.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/2837072.jpg',1,135,17.0,'一般','三級'),
('534',16,69,'望德堂區','三級',135,17.0,'一般',22.200108,113.548445,'official','534','T0000288','8635ed81-a471-11c8-8000-e9800050cec3',NULL,155.0,486.9,'常綠喬木；各部無毛，老樹常具鏽褐色氣根。葉薄革質，狹橢圓形，長4-8cm，寬3-4cm，全緣；托葉小，披針形。雌雄同株，榕果成對腋生或生於已落葉枝葉腋，熟時黃或微紅色，扁球形，徑6-8mm，無總柄，基生苞片3枚，廣卵形，宿存；榕果內花間有少許短剛毛，雄花無柄或具柄，散生內壁，花絲與花藥等長；雌花和癭花相似，花被片3枚，廣卵形，花柱近側生，柱頭短，棒形。瘦果卵圓形。花果期5-12月。','澳門區盧廉若公園','/photos/trees/534.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004867.jpg',1,135,17.0,'一般','三級'),
('247',21,88,'花地瑪堂區','三級',135,17.0,'一般',22.212218,113.53825,'official','247','T0000421','987e1249-f1dc-4989-8e4a-4f872521d299',NULL,68.4,215.0,'喬木，高達15m；嫩枝圓形，乾後灰白色。葉革質，寬或狹橢圓形，長6-12cm，寬3.5-7cm，頂端圓或鈍，有短尖頭，基部寬楔形，稀近圓形，葉面乾後褐色或黑褐色，背面色稍淺，具密小腺點；側脈多而密；葉柄長1-2cm。花3-5朵排成聚傘花序，並再組成圓錐花序狀的聚傘花序，此花序長可達11cm；花梗極短，花萼筒短小，漏斗形，花萼齒小；花瓣4，小，白色；雄蕊短。漿果，卵球形或壺形，直徑1-2cm，熟時有宿存萼齒；種子1枚。花期2-3月。','澳門區青洲山','/photos/trees/247.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005000.jpg',1,135,17.0,'一般','三級'),
('1051',9,63,'大堂區','三級',135,16.0,'一般',22.19094859,113.5444635,'official','1051','T0000528','69bbe583-b9fb-4d12-8aa9-b8c50a4d9fa6',NULL,238.0,747.7,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區澳門保安部隊事務局','/photos/trees/1051.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005110.jpg',1,135,16.0,'一般','三級'),
('246',17,88,'花地瑪堂區','三級',135,16.0,'一般',22.212295,113.536588,'official','246','T0000411','3609bc0c-9da8-417a-94bc-2d9c4da44b45',NULL,NULL,NULL,'常綠大喬木；高10-20(-30)m，胸徑達1-3m，樹冠大；具樟腦香氣；小枝無毛。葉薄革質，互生，卵狀橢圓形或長卵形，長6-12cm，寬2.5-6.5cm，頂端急尖，基部寬楔形至近圓形，邊緣多少波狀，葉面深綠色或黃綠色，有光澤，背面無毛或初時微被短柔毛；離基三出脈，側脈每邊2-5條，中脈在葉兩面均明顯，側脈在葉面上稍凸起，背面脈腋具明顯腺窩，窩內有短柔毛；葉柄長2-3cm。花多朵，排成圓錐花序狀的聚傘花序，花序長3.5-7cm，無毛或初時微被短柔毛；花黃白色或黃綠色，長約3mm，花被筒漏斗狀，花被裂片橢圓形，長約2mm，外面初時微被短柔毛，後脫落，內面密被短柔毛；子房近圓形，花柱短，柱頭頭狀。果近球形或卵球形，直徑6-8mm，熟時紫黑色，基部爲增大成淺杯狀或碟狀的果托所承托，果托邊緣全緣。花期4-5月；果期8-11月。','澳門區青洲山','/photos/trees/246.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004991.jpg',1,135,16.0,'一般','三級'),
('430',9,68,'花王堂區','三級',135,15.0,'一般',22.202139,113.539431,'official','430','T0000296','f618ce81-bbfd-11c8-8000-65df20910223',NULL,233.0,732.0,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區白鴿巢公園','/photos/trees/430.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004875.jpg',1,135,15.0,'一般','三級'),
('706',16,64,'花王堂區','三級',135,15.0,'一般',22.196775,113.542642,'official','706','T0000511','b4300bb7-c916-4abe-9edb-5235d9081aa2',NULL,161.0,505.8,'常綠喬木；各部無毛，老樹常具鏽褐色氣根。葉薄革質，狹橢圓形，長4-8cm，寬3-4cm，全緣；托葉小，披針形。雌雄同株，榕果成對腋生或生於已落葉枝葉腋，熟時黃或微紅色，扁球形，徑6-8mm，無總柄，基生苞片3枚，廣卵形，宿存；榕果內花間有少許短剛毛，雄花無柄或具柄，散生內壁，花絲與花藥等長；雌花和癭花相似，花被片3枚，廣卵形，花柱近側生，柱頭短，棒形。瘦果卵圓形。花果期5-12月。','澳門區澳門博物館','/photos/trees/706.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005093.jpg',1,135,15.0,'一般','三級'),
('718',10,52,'花地瑪堂區','三級',135,15.0,'一般',22.203963,113.550141,'official','718','T0000463','5782e479-c16d-4df6-8019-4d5828b6e461',NULL,76.0,238.8,'落葉大喬木，高可達25m以上；樹幹幼時有粗刺。掌狀複葉互生；葉柄稍長於小葉；小葉5-7片，長圓形至長圓狀披針形長10-20cm，寬3.5-7cm，頂端漸尖，基部闊楔形或漸窄，全緣，兩面無毛；小葉柄長約1.5-4cm。花紅色或橙紅色，直徑10-12cm，單生或聚生於近枝頂的葉腋；花萼杯狀，長2-4.5cm，內面被絹毛，3-5裂，裂片半圓形；花瓣帶肉質倒卵狀長圓形，長8-10cm，寬3-4cm，兩面多少有星狀細毛；雄蕊管短，花絲多數，外輪集成5組，與花瓣對生。蒴果長圓形，長10-15cm；種子藏於白色綿毛中。','澳門區普濟禪院（觀音堂）','/photos/trees/718.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005046.jpg',1,135,15.0,'一般','三級'),
('720',9,52,'花地瑪堂區','三級',135,15.0,'一般',22.204088,113.549805,'official','720','T0000473','00ccd5cf-1fec-418c-b5c7-05426af77d42',NULL,258.0,810.5,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區普濟禪院（觀音堂）','/photos/trees/720.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005056.jpg',1,135,15.0,'一般','三級'),
('1061',16,102,'聖方濟各堂區','三級',135,15.0,'一般',22.113913,113.550016,'official','1061','T0000586','9ad6ef86-5a56-4295-bdd2-b682ca7000de',NULL,NULL,NULL,'常綠喬木；各部無毛，老樹常具鏽褐色氣根。葉薄革質，狹橢圓形，長4-8cm，寬3-4cm，全緣；托葉小，披針形。雌雄同株，榕果成對腋生或生於已落葉枝葉腋，熟時黃或微紅色，扁球形，徑6-8mm，無總柄，基生苞片3枚，廣卵形，宿存；榕果內花間有少許短剛毛，雄花無柄或具柄，散生內壁，花絲與花藥等長；雌花和癭花相似，花被片3枚，廣卵形，花柱近側生，柱頭短，棒形。瘦果卵圓形。花果期5-12月。','路環區海事及水務局','/photos/trees/1061.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005173.jpg',1,135,15.0,'一般','三級'),
('490',35,68,'花王堂區','三級',135,14.0,'一般',22.201816,113.537114,'official','490','T0000322','84e57418-ffec-4ebf-a112-7c08ef45c51c',NULL,NULL,NULL,'大喬木，幼枝密被茸毛。葉大，革質，近圓形或長圓形，長24-34cm，寬14-29cm，頂端近截形，或近圓形，基部心形，邊緣全緣、淺裂或有粗齒；基出脈7-12條；葉柄粗壯。花單生，白色，芳香；萼片5枚，條狀長圓形，長達9cm，寬約7mm，外面被星狀毛；花瓣5片，條狀長圓形，比萼短；雄蕊15枚；子房長圓形，具5個棱角，5室，每室有胚珠多顆。蒴果木質，長圓狀圓筒形，長10-15cm，直徑5-5.5cm，初時被淡紅色茸毛；種子斜卵形，具翅；翅大而薄，褐色，光滑。','澳門區白鴿巢公園','/photos/trees/490.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1037763.jpg',1,135,14.0,'一般','三級'),
('512',46,68,'花王堂區','三級',135,14.0,'一般',22.198641,113.537587,'official','512','T0000093','304c8b89-0650-4a9e-8133-bf361daad8c7',NULL,81.0,254.5,'落葉喬木。二回羽狀複葉有羽片2-4對，葉軸上有腺體；小葉4-8對，長橢圓形，長2-4.5cm，寬1.3-2cm，頂端圓鈍或微凹，中脈略偏於上邊緣。頭狀花序直徑3-4cm，1至數個生於葉腋，總花梗長7-9mm；花冠黃綠色，芳香，長7-8mm。莢果帶狀，長15-28cm，寬2.5-4.5cm，扁平，麥桿色，常宿存於樹上經久不落。花期 5-9月；果期 10月至翌年5月。','澳門區白鴿巢前地','/photos/trees/512.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004658.jpg',1,135,14.0,'一般','三級'),
('469',5,68,'花王堂區','三級',135,11.0,'一般',22.199796,113.541208,'official','469','T0000312','0320dc01-c72d-11c8-8000-3eb0640c7303',NULL,NULL,NULL,'喬木，小枝初時被毛。葉薄革質，橢圓形、披針形或橢圓狀披針形，長9-20cm，寬3.5-8cm，頂端急尖，基部圓鈍，上面無毛，下面近無毛；側脈7-9對；葉柄長2.5-3.5cm。花淡紅色，萼齒5枚，僅基部連合，向外開展呈星狀，長圓狀披針形或長圓狀橢圓形，頂端有小尖凸，長4-6mm，外面被柔毛，邊緣有緣毛。蓇葖果紅色，厚革質，長圓狀卵形或長橢圓形，長5-7cm，寬2-2.5cm，被短絨毛，頂端有喙；種子黑褐色，橢圓狀卵形，直徑約1cm。花期4-5月；果期8-9月。','澳門區白鴿巢公園','/photos/trees/469.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/2728166.jpg',1,135,11.0,'一般','三級'),
('840',56,36,'大堂區','三級',135,11.0,'一般',22.192316,113.543865,'official','840','T0000340','f3077601-5f73-11c9-8000-3b014a847002',NULL,55.0,172.8,'常綠喬木，高達10m；小枝粗壯，被微柔毛，散生蒼白色皮孔。複葉連柄長15-30cm；小葉4-5對，薄革質，長圓狀橢圓形至長圓狀披針形，長6-15cm，寬2.5-5cm，基部極不對稱；小葉柄長不及5mm。花序大型，多分枝，頂生和近枝頂腋生，密被星狀毛；萼片近革質，覆瓦狀排列，兩面均被褐黃色絨毛和成束的星狀毛；花瓣乳白色；花絲被短硬毛。果近球形，黃褐色或灰黃色，外面稍粗糙。花期春夏間；果期夏季。','澳門區加思欄花園','/photos/trees/840.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004916.jpg',1,135,11.0,'一般','三級'),
('364',24,23,'風順堂區','三級',135,11.0,'一般',22.187334,113.535348,'official','364','T0000502','99036640-72bf-47e6-b7cd-fd0f0ed3f60d',NULL,NULL,NULL,'落葉喬木。樹皮灰褐色或黑褐色；嫩枝綠色，無毛。葉連柄長25-45cm，葉軸稍扁，上面兩側具直槽；小葉5-8對，葉片薄紙質，長橢圓狀披針形或稍呈鐮形，長7-15cm，寬2-5cm，基部楔形，稍不對稱；小葉柄長約5mm。花序頂生，圓錐形；花小，輻射對稱；花瓣5，披針形，具長爪，外面基部具2鱗片；花盤碟狀，無毛；雄蕊8枚；子房無毛。果橙黃色，乾時變黑。花期春季；果期夏秋。','澳門區主教山小堂','/photos/trees/364.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005084.jpg',1,135,11.0,'一般','三級'),
('1111',20,49,'花王堂區','三級',135,11.0,'一般',22.20421271929587,113.54898592152522,'official','1111','T0034368','16b2b07c-9772-4f34-b78b-0ec3551aa146',NULL,64.0,201.1,'喬木，高達12m；嫩枝扁。葉薄革質，橢圓形或長圓形，長10-22cm，寬5-8cm，頂端鈍或稍尖，基部變狹，圓形或微心形，葉面乾後變黃褐色，背面具密小腺點；側脈14-19對，網脈明顯；葉柄極短。花數朵，排成聚傘花序，花序長5-6cm，花3-5朵排成聚傘花序，花梗極短；花萼筒短小，漏斗形，花萼齒小，4枚；花瓣4，小，白色；雄蕊短。漿果，梨形或圓錐形，亮紅色，直徑2-4cm，頂部凹陷，熟時有宿存、肉質的萼齒；種子1枚。花期3-4月；果期5-6月。','澳門區庇道學校','/photos/trees/1111.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1347617.jpg',1,135,11.0,'一般','三級'),
('826',24,36,'大堂區','三級',135,10.0,'一般',22.192945,113.544166,'official','826','T0000333','614a3981-5f70-11c9-8000-3b014a847002',NULL,54.0,169.6,'落葉喬木。樹皮灰褐色或黑褐色；嫩枝綠色，無毛。葉連柄長25-45cm，葉軸稍扁，上面兩側具直槽；小葉5-8對，葉片薄紙質，長橢圓狀披針形或稍呈鐮形，長7-15cm，寬2-5cm，基部楔形，稍不對稱；小葉柄長約5mm。花序頂生，圓錐形；花小，輻射對稱；花瓣5，披針形，具長爪，外面基部具2鱗片；花盤碟狀，無毛；雄蕊8枚；子房無毛。果橙黃色，乾時變黑。花期春季；果期夏秋。','澳門區加思欄花園','/photos/trees/826.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1058216.jpg',1,135,10.0,'一般','三級'),
('221',36,88,'花地瑪堂區','三級',135,10.0,'一般',22.211695,113.53681,'official','221','T0000409','47a2e890-5ded-4664-b4f9-14a6eb9f30aa',NULL,49.3,155.0,'常綠喬木。葉革質，二型，生於幼樹或萌蘗枝上的葉盾形， 直徑約1 5 cm，掌狀3 - 5裂， 上面幾無毛，下面密被褐色星狀短柔毛；葉柄長約1 2 cm， 被毛， 生於成長樹上的葉長圓形至卵狀長圓形，頂端漸尖或鈍，基部斜圓形或斜心形， 長7-15cm，寬3-10cm，下面密被黃褐色短柔毛；葉柄長1-2cm。花單生或2-4朵組成腋生的聚傘花序；萼裂片條形，長約2.5cm，兩面均被柔毛；花瓣白色，倒披針形，與萼片等長；雌雄蕊柄長2.5cm，雄蕊15枚，每3個組成一組；子房卵圓形，被毛。蒴果木質，長圓狀卵形，長4-6cm，寬2-2.5cm，被黃褐色絨毛 ; 種子頂端具膜質翅。花期6-7月 ; 果期8-12月。','澳門區青洲山','/photos/trees/221.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004989.jpg',1,135,10.0,'一般','三級'),
('49',11,126,'聖方濟各堂區','三級',135,10.0,'一般',22.123128,113.570293,'official','49','T0000345','70888601-8ee9-11ca-8000-8c3777d92863',NULL,NULL,NULL,'別名為朴樹。落葉喬木，高可達10m；小枝幼時密被短柔毛。葉紙質；葉柄長5-10mm，被短柔毛；葉片卵形或長卵形，長5-10cm，寬2.5-5 cm，頂端短漸尖，基部近圓形，稍偏斜，邊緣中部以上通常有鋸齒，幼時兩面被柔毛，後脫落；基部3出脈在下面明顯凸起。雄花在新枝下部排成聚傘花序，雌花1-3朵生於枝上部葉腋間。核果近球形，直徑約5mm；果梗長約1cm。花期3-4月；果期9-10月。','路環區黑沙海灘公園','/photos/trees/49.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004925.jpg',1,135,10.0,'一般','三級'),
('533',56,69,'望德堂區','三級',135,8.0,'一般',22.200603,113.54767,'official','533','T0000249','d4582f01-7259-11c2-8000-d029ef855be3',NULL,63.0,197.9,'常綠喬木，高達10m；小枝粗壯，被微柔毛，散生蒼白色皮孔。複葉連柄長15-30cm；小葉4-5對，薄革質，長圓狀橢圓形至長圓狀披針形，長6-15cm，寬2.5-5cm，基部極不對稱；小葉柄長不及5mm。花序大型，多分枝，頂生和近枝頂腋生，密被星狀毛；萼片近革質，覆瓦狀排列，兩面均被褐黃色絨毛和成束的星狀毛；花瓣乳白色；花絲被短硬毛。果近球形，黃褐色或灰黃色，外面稍粗糙。花期春夏間；果期夏季。','澳門區盧廉若公園','/photos/trees/533.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004828.jpg',1,135,8.0,'一般','三級'),
('777',47,90,'花地瑪堂區','三級',135,6.0,'一般',22.20326934,113.5555914,'official','777','T0000378','aa6566ed-9dc6-48c4-b792-5f10faeefc23',NULL,NULL,NULL,'落葉喬木，高達8m；枝條粗壯，帶肉質，具豐富乳汁，葉痕明顯。葉厚紙質，長圓狀倒披針形或長橢圓形，兩面無毛；中脈在上面凹陷，側脈30-40對；葉柄上面基部具腺體，無毛。花冠外在上面凹陷，側脈30-40對；葉柄上面基部具腺體，無毛。花冠外黃色，外面無毛，內面密被柔毛，喉部無鱗片。蓇葖果圓筒形。花期5-10月；果期7-12月。','澳門區馬交石炮台公園','/photos/trees/777.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1007978.jpg',1,135,6.0,'一般','三級'),
('882',1,30,'風順堂區','三級',135,6.0,'一般',22.192358,113.537209,'official','882','T0000486','5a7f4e46-a332-4367-b37c-c1285a92b7e8',NULL,NULL,NULL,'灌木或小喬木，高2-10m，樹幹及小枝灰白色。奇數羽狀複葉，小葉3-5片，互生，卵形或卵狀披針形，小葉長1-3 cm，寬0.5-1.5 cm，兩側對稱或一側偏斜，全緣。花序腋生及頂生，通常花5-10朵，萼片卵形，花瓣白色，披針形，盛花時反折，雄蕊10枚，花絲白色。果橙黃至朱紅色，狹長橢圓形，長l-2 cm，寬0.5-1.5mm。花期4-9月；果期9-12月。','澳門區何東圖書館','/photos/trees/882.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005069.jpg',1,135,6.0,'一般','三級'),
('1123',47,77,'大堂區','三級',135,5.0,'一般',22.19357324,113.5417826,'official','1123','T0000518','e216c7bb-59df-49fd-aca7-7cd338a46013',NULL,NULL,NULL,'落葉喬木，高達8m；枝條粗壯，帶肉質，具豐富乳汁，葉痕明顯。葉厚紙質，長圓狀倒披針形或長橢圓形，兩面無毛；中脈在上面凹陷，側脈30-40對；葉柄上面基部具腺體，無毛。花冠外在上面凹陷，側脈30-40對；葉柄上面基部具腺體，無毛。花冠外黃色，外面無毛，內面密被柔毛，喉部無鱗片。蓇葖果圓筒形。花期5-10月；果期7-12月。','澳門區聖若瑟教區中學','/photos/trees/1123.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1054732.jpg',1,135,5.0,'一般','三級'),
('792',10,80,'花地瑪堂區','三級',135,25.0,'健康',22.20946201,113.5477261,'official','792','T0000414','3c11c4f5-d320-420a-a1c1-3498c636cf31',13.5,99.0,311.0,'落葉大喬木，高可達25m以上；樹幹幼時有粗刺。掌狀複葉互生；葉柄稍長於小葉；小葉5-7片，長圓形至長圓狀披針形長10-20cm，寬3.5-7cm，頂端漸尖，基部闊楔形或漸窄，全緣，兩面無毛；小葉柄長約1.5-4cm。花紅色或橙紅色，直徑10-12cm，單生或聚生於近枝頂的葉腋；花萼杯狀，長2-4.5cm，內面被絹毛，3-5裂，裂片半圓形；花瓣帶肉質倒卵狀長圓形，長8-10cm，寬3-4cm，兩面多少有星狀細毛；雄蕊管短，花絲多數，外輪集成5組，與花瓣對生。蒴果長圓形，長10-15cm；種子藏於白色綿毛中。','澳門區蓮峯廟','/photos/trees/792.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004994.jpg',1,135,25.0,'健康','三級'),
('438',9,68,'花王堂區','三級',135,23.0,'健康',22.201466,113.540887,'official','438','T0000305','291fd281-bf1c-11c8-8000-5708262460c3',NULL,174.0,546.6,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區白鴿巢公園','/photos/trees/438.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004884.jpg',1,135,23.0,'健康','三級'),
('437',9,68,'花王堂區','三級',135,22.0,'健康',22.200951,113.537386,'official','437','T0000308','abab9081-bf22-11c8-8000-5708262460c3',NULL,162.0,508.9,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區白鴿巢公園','/photos/trees/437.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004887.jpg',1,135,22.0,'健康','三級'),
('440',9,68,'花王堂區','三級',135,20.0,'健康',22.198792,113.53859,'official','440','T0000306','b7e21e81-bf1f-11c8-8000-5708262460c3',NULL,117.0,367.6,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區白鴿巢公園','/photos/trees/440.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004885.jpg',1,135,20.0,'健康','三級'),
('702',19,107,'聖方濟各堂區','三級',135,17.3,'健康',22.125605,113.55686,'official','702','T0000571','6a4d7f2c-64e9-4e86-be97-479ef55594f5',NULL,NULL,NULL,'喬木，高可達15m；樹皮厚，灰褐色，不開裂，分枝多。葉對生，薄革質，長圓形或橢圓形，長11-17 cm，寬4.5-7 cm，頂端急尖或漸尖，基部寬楔形或略圓，兩面多透明腺點；側脈9-13對，網脈明顯；葉柄長1-2cm。花無梗，2-3朵聚生，並排成圓錐花序狀的聚傘花序，花序着生在老枝上，長6-12cm；花萼筒半球形，花萼片合生成帽蓋狀，其頂端成短喙；雄蕊較花柱長。漿柱長。漿果，寬卵球形，直徑10-13mm。花期5-6月。','路環區石排灣郊野公園','/photos/trees/702.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005153.jpg',1,135,17.3,'健康','三級'),
('1102',16,91,'花王堂區','三級',135,15.0,'健康',22.1980642,113.5404888,'official','1102','T0000403','1a2ce01a-06a6-45a7-be0e-7f84444fdb78',NULL,156.0,490.1,'常綠喬木；各部無毛，老樹常具鏽褐色氣根。葉薄革質，狹橢圓形，長4-8cm，寬3-4cm，全緣；托葉小，披針形。雌雄同株，榕果成對腋生或生於已落葉枝葉腋，熟時黃或微紅色，扁球形，徑6-8mm，無總柄，基生苞片3枚，廣卵形，宿存；榕果內花間有少許短剛毛，雄花無柄或具柄，散生內壁，花絲與花藥等長；雌花和癭花相似，花被片3枚，廣卵形，花柱近側生，柱頭短，棒形。瘦果卵圓形。花果期5-12月。','澳門區高園街','/photos/trees/1102.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1049802.jpg',1,135,15.0,'健康','三級'),
('16',33,96,'聖方濟各堂區','三級',135,5.0,'瀕危',22.132051,113.588713,'official','16','T0034448','96a00e7b-ad27-445d-b8e9-42479e7d6fea',NULL,NULL,NULL,'灌木或小喬木；幼枝四棱形，略成翅狀。葉互生，稀對生，橢圓形或倒卵形，長2-6 cm，寬1.5-3 cm，頂端尖或近圓形，有時微凹陷，基部楔形或近圓形。圓錐花序，花淡紅色或紫色，盛開時直徑可達3-4 cm；花萼具微棱，具6枚三角形的裂片；花瓣6枚，皺縮，長12-20mm，具長爪；雄蕊36-42枚，其中較長的6枚生於萼管上；子房3-6室。蒴果橢球形，長約1.5cm，寬約1cm；種子長8mm。花期6-9月；果期9-12月。','路環區九澳聖母馬路','/photos/trees/16.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1281284.jpg',1,135,5.0,'瀕危','三級'),
('520',56,69,'望德堂區','三級',135,4.5,'瀕危',22.200414,113.548166,'official','520','T0000277','d181ca81-a3a3-11c8-8000-e9800050cec3',NULL,38.0,119.4,'常綠喬木，高達10m；小枝粗壯，被微柔毛，散生蒼白色皮孔。複葉連柄長15-30cm；小葉4-5對，薄革質，長圓狀橢圓形至長圓狀披針形，長6-15cm，寬2.5-5cm，基部極不對稱；小葉柄長不及5mm。花序大型，多分枝，頂生和近枝頂腋生，密被星狀毛；萼片近革質，覆瓦狀排列，兩面均被褐黃色絨毛和成束的星狀毛；花瓣乳白色；花絲被短硬毛。果近球形，黃褐色或灰黃色，外面稍粗糙。花期春夏間；果期夏季。','澳門區盧廉若公園','/photos/trees/520.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004856.jpg',1,135,4.5,'瀕危','三級'),
('1134',9,75,'風順堂區','三級',133,16.0,'健康',22.18259,113.531042,'official','1134','T0101351','e3c39955-7479-4aa4-9304-9f2cbfe5daab',NULL,313.0,983.3,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區聖地牙哥酒店','/photos/trees/1134.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1804419.jpg',1,133,16.0,'健康','三級'),
('214',16,88,'花地瑪堂區','三級',125,30.0,'一般',22.21134,113.538314,'official','214','T0000432','bf5fef82-900a-41d0-9ac6-ac4219c84a7e',NULL,146.4,460.0,'常綠喬木；各部無毛，老樹常具鏽褐色氣根。葉薄革質，狹橢圓形，長4-8cm，寬3-4cm，全緣；托葉小，披針形。雌雄同株，榕果成對腋生或生於已落葉枝葉腋，熟時黃或微紅色，扁球形，徑6-8mm，無總柄，基生苞片3枚，廣卵形，宿存；榕果內花間有少許短剛毛，雄花無柄或具柄，散生內壁，花絲與花藥等長；雌花和癭花相似，花被片3枚，廣卵形，花柱近側生，柱頭短，棒形。瘦果卵圓形。花果期5-12月。','澳門區青洲山','/photos/trees/214.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005011.jpg',1,125,30.0,'一般','三級'),
('273',51,57,'望德堂區','三級',125,23.5,'一般',22.200341,113.552428,'official','273','T0000361','96f86539-ccd3-4443-897a-a5430bf39084',8.0,151.0,474.4,'喬木；幼枝綠色，被微柔毛。葉厚革質，寬卵形至寬卵狀橢圓形，長10-19cm，寬8-11cm，全緣，兩面無毛；托葉厚革質，長2-3cm，被灰色絲毛。雌雄同株，榕果成對腋生，橢圓狀卵圓形，徑1.7-2.8cm，無總柄，幼時包於早落風帽狀苞片內，熟時紅或帶黃色，基生苞片短寬，脫落後環狀；雄花散生榕果內壁，花被片4片，雄蕊1枚；雌花無梗，花被片與癭花同數，花柱長，柱頭棒狀，子房基部具紅斑。瘦果表面具小瘤。花果期3-10月。','澳門區松山市政公園','/photos/trees/273.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/866859.jpg',1,125,23.5,'一般','三級'),
('203',56,88,'花地瑪堂區','三級',125,23.0,'一般',22.212943,113.537128,'official','203','T0000425','2a1dc029-3a4f-45ce-a4f8-7ea8e6de01e4',NULL,50.9,160.0,'常綠喬木，高達10m；小枝粗壯，被微柔毛，散生蒼白色皮孔。複葉連柄長15-30cm；小葉4-5對，薄革質，長圓狀橢圓形至長圓狀披針形，長6-15cm，寬2.5-5cm，基部極不對稱；小葉柄長不及5mm。花序大型，多分枝，頂生和近枝頂腋生，密被星狀毛；萼片近革質，覆瓦狀排列，兩面均被褐黃色絨毛和成束的星狀毛；花瓣乳白色；花絲被短硬毛。果近球形，黃褐色或灰黃色，外面稍粗糙。花期春夏間；果期夏季。','澳門區青洲山','/photos/trees/203.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005004.jpg',1,125,23.0,'一般','三級'),
('241',21,88,'花地瑪堂區','三級',125,22.0,'一般',22.212894,113.538212,'official','241','T0000441','449de41c-61a5-4dce-9254-d8c2a881b762',NULL,78.0,245.0,'喬木，高達15m；嫩枝圓形，乾後灰白色。葉革質，寬或狹橢圓形，長6-12cm，寬3.5-7cm，頂端圓或鈍，有短尖頭，基部寬楔形，稀近圓形，葉面乾後褐色或黑褐色，背面色稍淺，具密小腺點；側脈多而密；葉柄長1-2cm。花3-5朵排成聚傘花序，並再組成圓錐花序狀的聚傘花序，此花序長可達11cm；花梗極短，花萼筒短小，漏斗形，花萼齒小；花瓣4，小，白色；雄蕊短。漿果，卵球形或壺形，直徑1-2cm，熟時有宿存萼齒；種子1枚。花期2-3月。','澳門區青洲山','/photos/trees/241.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005020.jpg',1,125,22.0,'一般','三級'),
('17',9,96,'聖方濟各堂區','三級',125,22.0,'一般',22.131678,113.588877,'official','17','T0000032','f22f2b26-f585-4ddf-8700-a7f3080c83ce',5.0,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區九澳聖母馬路','/photos/trees/17.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004593.jpg',1,125,22.0,'一般','三級'),
('442',4,68,'花王堂區','三級',125,20.0,'一般',22.203079,113.538979,'official','442','T0000302','dcdb8f01-bf29-11c8-8000-5708262460c3',NULL,69.0,216.8,'常綠喬木，高達18m；樹皮灰色或灰褐色；芽鱗、小枝密被鏽色短柔毛。葉薄革質，互生，寬卵形、倒卵形至卵狀長圓形，長8-20cm，寬4-12cm，頂端鈍或圓，偶有急尖，基部圓或急尖，幼葉上面沿中脈有鏽色短柔毛，老時漸脫落變無毛，背面密被鏽色短柔毛；羽狀脈，側脈每邊8-12條，有近平行的橫脈相聯，中脈、側脈在葉面下陷；葉柄長1-3cm，密被鏽色短柔毛。花4-6朵或更多，排成傘形花序狀的聚傘花序，花序梗極短；苞片膜質；花梗有鏽色柔毛；能育雄蕊9枚，花絲纖細，有柔毛。果長卵形，直徑5mm，果托淺碟狀，果梗短。花期11月至翌年6月；果期6-7月。','澳門區白鴿巢公園','/photos/trees/442.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004881.jpg',1,125,20.0,'一般','三級'),
('801',9,66,'花地瑪堂區','三級',125,20.0,'一般',22.20755052,113.5463941,'official','801','T0000263','196cf881-4049-11c6-8000-6c84e25e79e3',NULL,259.0,813.7,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區澳門市政狗房','/photos/trees/801.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004842.jpg',1,125,20.0,'一般','三級'),
('229',36,88,'花地瑪堂區','三級',125,20.0,'一般',22.211812,113.53613,'official','229','T0000410','a123806d-f658-4d9b-88ea-15161163389c',NULL,48.4,152.0,'常綠喬木。葉革質，二型，生於幼樹或萌蘗枝上的葉盾形， 直徑約1 5 cm，掌狀3 - 5裂， 上面幾無毛，下面密被褐色星狀短柔毛；葉柄長約1 2 cm， 被毛， 生於成長樹上的葉長圓形至卵狀長圓形，頂端漸尖或鈍，基部斜圓形或斜心形， 長7-15cm，寬3-10cm，下面密被黃褐色短柔毛；葉柄長1-2cm。花單生或2-4朵組成腋生的聚傘花序；萼裂片條形，長約2.5cm，兩面均被柔毛；花瓣白色，倒披針形，與萼片等長；雌雄蕊柄長2.5cm，雄蕊15枚，每3個組成一組；子房卵圓形，被毛。蒴果木質，長圓狀卵形，長4-6cm，寬2-2.5cm，被黃褐色絨毛 ; 種子頂端具膜質翅。花期6-7月 ; 果期8-12月。','澳門區青洲山','/photos/trees/229.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004990.jpg',1,125,20.0,'一般','三級'),
('2',9,107,'聖方濟各堂區','三級',125,20.0,'一般',22.12573,113.556524,'official','2','T0000368','db795401-d5e1-11ca-8000-3b2e11c83a03',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區石排灣郊野公園','/photos/trees/2.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004948.jpg',1,125,20.0,'一般','三級'),
('22',9,96,'聖方濟各堂區','三級',125,20.0,'一般',22.131767,113.588394,'official','22','T0000221','7e27ba2b-4924-4717-868e-5410bb387736',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區九澳聖母馬路','/photos/trees/22.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004799.jpg',1,125,20.0,'一般','三級'),
('350',17,57,'望德堂區','三級',125,19.0,'一般',22.199858,113.55197,'official','350','T0000485','179eaf5d-389d-4fbc-8087-d435515637d5',10.0,80.0,251.3,'常綠大喬木；高10-20(-30)m，胸徑達1-3m，樹冠大；具樟腦香氣；小枝無毛。葉薄革質，互生，卵狀橢圓形或長卵形，長6-12cm，寬2.5-6.5cm，頂端急尖，基部寬楔形至近圓形，邊緣多少波狀，葉面深綠色或黃綠色，有光澤，背面無毛或初時微被短柔毛；離基三出脈，側脈每邊2-5條，中脈在葉兩面均明顯，側脈在葉面上稍凸起，背面脈腋具明顯腺窩，窩內有短柔毛；葉柄長2-3cm。花多朵，排成圓錐花序狀的聚傘花序，花序長3.5-7cm，無毛或初時微被短柔毛；花黃白色或黃綠色，長約3mm，花被筒漏斗狀，花被裂片橢圓形，長約2mm，外面初時微被短柔毛，後脫落，內面密被短柔毛；子房近圓形，花柱短，柱頭頭狀。果近球形或卵球形，直徑6-8mm，熟時紫黑色，基部爲增大成淺杯狀或碟狀的果托所承托，果托邊緣全緣。花期4-5月；果期8-11月。','澳門區松山市政公園','/photos/trees/350.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005068.jpg',1,125,19.0,'一般','三級'),
('88',9,110,'聖方濟各堂區','三級',125,19.0,'一般',22.118431,113.555345,'official','88','T0000324','65f0d801-339b-11c9-8000-36e87f6c3423',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區竹灣馬路','/photos/trees/88.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/986765.jpg',1,125,19.0,'一般','三級'),
('97',9,110,'聖方濟各堂區','三級',125,18.5,'一般',22.118106,113.556007,'official','97','T0000096','d403a0ba-d115-4812-9504-c6b81a6952ef',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區竹灣馬路','/photos/trees/97.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004661.jpg',1,125,18.5,'一般','三級'),
('257',51,57,'望德堂區','三級',125,18.0,'一般',22.200614,113.553441,'official','257','T0000354','a792f880-6244-4300-b721-447df8314e9a',12.0,183.0,574.9,'喬木；幼枝綠色，被微柔毛。葉厚革質，寬卵形至寬卵狀橢圓形，長10-19cm，寬8-11cm，全緣，兩面無毛；托葉厚革質，長2-3cm，被灰色絲毛。雌雄同株，榕果成對腋生，橢圓狀卵圓形，徑1.7-2.8cm，無總柄，幼時包於早落風帽狀苞片內，熟時紅或帶黃色，基生苞片短寬，脫落後環狀；雄花散生榕果內壁，花被片4片，雄蕊1枚；雌花無梗，花被片與癭花同數，花柱長，柱頭棒狀，子房基部具紅斑。瘦果表面具小瘤。花果期3-10月。','澳門區松山市政公園','/photos/trees/257.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004934.jpg',1,125,18.0,'一般','三級'),
('476',28,68,'花王堂區','三級',125,18.0,'一般',22.198816,113.541254,'official','476','T0000472','2b4ab889-1498-49d9-8051-0441554052e0',NULL,71.0,223.1,'常綠喬木，高達20m；嫩枝密被星狀短柔毛。葉倒卵形或近菱形，全緣或3-5淺裂，頂端短漸尖，基部闊楔形、圓鈍或淺心形，無毛或下面疏被星狀毛；葉柄頂端有2枚腺體。花雌雄同株，聚傘圓錐花序頂生，長7-15cm，密被星狀短柔毛；雄花花萼長約3mm，常2深裂，雄蕊15-20枚，排成3-4輪，着生於突起的花托上；雌花子房密被毛，每室具1顆胚珠，花柱2裂。核果近圓球形，有種子1-2顆；種子扁球形，種皮具疣狀突棱。','澳門區白鴿巢公園','/photos/trees/476.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005055.jpg',1,125,18.0,'一般','三級'),
('833',46,36,'大堂區','三級',125,18.0,'一般',22.191917,113.544712,'official','833','T0000337','aa9b8881-5f72-11c9-8000-3b014a847002',NULL,98.0,307.9,'落葉喬木。二回羽狀複葉有羽片2-4對，葉軸上有腺體；小葉4-8對，長橢圓形，長2-4.5cm，寬1.3-2cm，頂端圓鈍或微凹，中脈略偏於上邊緣。頭狀花序直徑3-4cm，1至數個生於葉腋，總花梗長7-9mm；花冠黃綠色，芳香，長7-8mm。莢果帶狀，長15-28cm，寬2.5-4.5cm，扁平，麥桿色，常宿存於樹上經久不落。花期 5-9月；果期 10月至翌年5月。','澳門區加思欄花園','/photos/trees/833.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004913.jpg',1,125,18.0,'一般','三級');
insert into public.trees (tree_no,species_id,site_id,parish_code,grade,age_years,height_m,health,lat,lon,geo_precision,official_no,iam_tree_no,ref_id,crown_m,diameter_cm,surround_m,official_description,official_loc,photo_url,photo_source,photo_count,official_age_years,official_height_m,official_health,official_grade) values
('242',21,88,'花地瑪堂區','三級',125,18.0,'一般',22.210668,113.537419,'official','242','T0000419','a290a27e-f9c4-4f59-ba41-696e02befc12',NULL,78.3,246.0,'喬木，高達15m；嫩枝圓形，乾後灰白色。葉革質，寬或狹橢圓形，長6-12cm，寬3.5-7cm，頂端圓或鈍，有短尖頭，基部寬楔形，稀近圓形，葉面乾後褐色或黑褐色，背面色稍淺，具密小腺點；側脈多而密；葉柄長1-2cm。花3-5朵排成聚傘花序，並再組成圓錐花序狀的聚傘花序，此花序長可達11cm；花梗極短，花萼筒短小，漏斗形，花萼齒小；花瓣4，小，白色；雄蕊短。漿果，卵球形或壺形，直徑1-2cm，熟時有宿存萼齒；種子1枚。花期2-3月。','澳門區青洲山','/photos/trees/242.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004998.jpg',1,125,18.0,'一般','三級'),
