('152',9,101,'聖方濟各堂區','三級',125,13.0,'健康',22.116019,113.552083,'official','152','T0000137','48a76340-431c-4130-a868-f3f34b6df43b',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區民國馬路','/photos/trees/152.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004706.jpg',1,125,13.0,'健康','三級'),
('160',9,101,'聖方濟各堂區','三級',125,13.0,'健康',22.116102,113.552724,'official','160','T0000088','76f86a9f-7150-473b-8010-b8857f29e21e',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區民國馬路','/photos/trees/160.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1013691.jpg',1,125,13.0,'健康','三級'),
('923',24,20,'嘉模堂區','三級',125,12.01,'健康',22.162122,113.558893,'official','923','T0034388','ac87e745-11d6-40f2-9d1b-e2e936c7c541',NULL,NULL,NULL,'落葉喬木。樹皮灰褐色或黑褐色；嫩枝綠色，無毛。葉連柄長25-45cm，葉軸稍扁，上面兩側具直槽；小葉5-8對，葉片薄紙質，長橢圓狀披針形或稍呈鐮形，長7-15cm，寬2-5cm，基部楔形，稍不對稱；小葉柄長約5mm。花序頂生，圓錐形；花小，輻射對稱；花瓣5，披針形，具長爪，外面基部具2鱗片；花盤碟狀，無毛；雄蕊8枚；子房無毛。果橙黃色，乾時變黑。花期春季；果期夏秋。','氹仔區關帝殿及天后宮','/photos/trees/923.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1767291.jpg',1,125,12.01,'健康','三級');
insert into public.trees (tree_no,species_id,site_id,parish_code,grade,age_years,height_m,health,lat,lon,geo_precision,official_no,iam_tree_no,ref_id,crown_m,diameter_cm,surround_m,official_description,official_loc,photo_url,photo_source,photo_count,official_age_years,official_height_m,official_health,official_grade) values
('922',56,5,'嘉模堂區','三級',125,12.0,'健康',22.162165051080006,113.5582544884176,'official','922','T0034430','660a4f07-83c0-4b61-b302-212c4d7ac57f',NULL,64.97,204.1,'常綠喬木，高達10m；小枝粗壯，被微柔毛，散生蒼白色皮孔。複葉連柄長15-30cm；小葉4-5對，薄革質，長圓狀橢圓形至長圓狀披針形，長6-15cm，寬2.5-5cm，基部極不對稱；小葉柄長不及5mm。花序大型，多分枝，頂生和近枝頂腋生，密被星狀毛；萼片近革質，覆瓦狀排列，兩面均被褐黃色絨毛和成束的星狀毛；花瓣乳白色；花絲被短硬毛。果近球形，黃褐色或灰黃色，外面稍粗糙。花期春夏間；果期夏季。','氹仔區天津街','/photos/trees/922.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/2739344.jpg',1,125,12.0,'健康','三級'),
('158',9,101,'聖方濟各堂區','三級',125,12.0,'健康',22.11518,113.552132,'official','158','T0000139','45d0921a-a593-4563-b636-02c1704c5ece',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區民國馬路','/photos/trees/158.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1013687.jpg',1,125,12.0,'健康','三級'),
('6',9,107,'聖方濟各堂區','三級',125,16.0,'瀕危',22.125357,113.556688,'official','6','T0000370','2f982e81-d60a-11ca-8000-29e0b9c38722',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區石排灣郊野公園','/photos/trees/6.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004950.jpg',1,125,16.0,'瀕危','三級'),
('565',17,18,'嘉模堂區','三級',125,12.01,'瀕危',22.15477074,113.5596595,'official','565','T0000118','bcbe2102-8dbd-46cd-a67d-dce63848febe',NULL,NULL,NULL,'常綠大喬木；高10-20(-30)m，胸徑達1-3m，樹冠大；具樟腦香氣；小枝無毛。葉薄革質，互生，卵狀橢圓形或長卵形，長6-12cm，寬2.5-6.5cm，頂端急尖，基部寬楔形至近圓形，邊緣多少波狀，葉面深綠色或黃綠色，有光澤，背面無毛或初時微被短柔毛；離基三出脈，側脈每邊2-5條，中脈在葉兩面均明顯，側脈在葉面上稍凸起，背面脈腋具明顯腺窩，窩內有短柔毛；葉柄長2-3cm。花多朵，排成圓錐花序狀的聚傘花序，花序長3.5-7cm，無毛或初時微被短柔毛；花黃白色或黃綠色，長約3mm，花被筒漏斗狀，花被裂片橢圓形，長約2mm，外面初時微被短柔毛，後脫落，內面密被短柔毛；子房近圓形，花柱短，柱頭頭狀。果近球形或卵球形，直徑6-8mm，熟時紫黑色，基部爲增大成淺杯狀或碟狀的果托所承托，果托邊緣全緣。花期4-5月；果期8-11月。','氹仔區素啤古街','/photos/trees/565.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/52100.jpg',1,125,12.01,'瀕危','三級'),
('79',9,110,'聖方濟各堂區','三級',125,10.0,'瀕危',22.118536,113.554207,'official','79','T0000120','cfca72de-bbc6-49ca-909d-df46f633f0ee',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區竹灣馬路','/photos/trees/79.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1010952.jpg',1,125,10.0,'瀕危','三級'),
('306',17,57,'望德堂區','三級',125,8.0,'瀕危',22.200989,113.552968,'official','306','T0000496','6d3fea94-2640-463d-bb7f-4f29739b1a17',8.0,94.0,295.3,'常綠大喬木；高10-20(-30)m，胸徑達1-3m，樹冠大；具樟腦香氣；小枝無毛。葉薄革質，互生，卵狀橢圓形或長卵形，長6-12cm，寬2.5-6.5cm，頂端急尖，基部寬楔形至近圓形，邊緣多少波狀，葉面深綠色或黃綠色，有光澤，背面無毛或初時微被短柔毛；離基三出脈，側脈每邊2-5條，中脈在葉兩面均明顯，側脈在葉面上稍凸起，背面脈腋具明顯腺窩，窩內有短柔毛；葉柄長2-3cm。花多朵，排成圓錐花序狀的聚傘花序，花序長3.5-7cm，無毛或初時微被短柔毛；花黃白色或黃綠色，長約3mm，花被筒漏斗狀，花被裂片橢圓形，長約2mm，外面初時微被短柔毛，後脫落，內面密被短柔毛；子房近圓形，花柱短，柱頭頭狀。果近球形或卵球形，直徑6-8mm，熟時紫黑色，基部爲增大成淺杯狀或碟狀的果托所承托，果托邊緣全緣。花期4-5月；果期8-11月。','澳門區松山市政公園','/photos/trees/306.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1518894.jpg',1,125,8.0,'瀕危','三級'),
('92',9,110,'聖方濟各堂區','三級',125,8.0,'瀕危',22.117552,113.555409,'official','92','T0000556','a8e9bdb8-a1ad-4208-b314-fc5fa81a8a0f',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區竹灣馬路','/photos/trees/92.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005138.jpg',1,125,8.0,'瀕危','三級'),
('832',46,36,'大堂區','三級',125,2.0,'瀕危',22.193189,113.544656,'official','832','T0000336','2fd26d81-5f72-11c9-8000-3b014a847002',NULL,89.0,279.6,'落葉喬木。二回羽狀複葉有羽片2-4對，葉軸上有腺體；小葉4-8對，長橢圓形，長2-4.5cm，寬1.3-2cm，頂端圓鈍或微凹，中脈略偏於上邊緣。頭狀花序直徑3-4cm，1至數個生於葉腋，總花梗長7-9mm；花冠黃綠色，芳香，長7-8mm。莢果帶狀，長15-28cm，寬2.5-4.5cm，扁平，麥桿色，常宿存於樹上經久不落。花期 5-9月；果期 10月至翌年5月。','澳門區加思欄花園','/photos/trees/832.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1519742.jpg',1,125,2.0,'瀕危','三級'),
('601',11,21,'嘉模堂區','三級',123,12.0,'一般',22.155982,113.560069,'official','601','T0034607','24d57be0-31fa-41f0-aeca-9e314206448d',6.0,87.0,273.3,'別名為朴樹。落葉喬木，高可達10m；小枝幼時密被短柔毛。葉紙質；葉柄長5-10mm，被短柔毛；葉片卵形或長卵形，長5-10cm，寬2.5-5 cm，頂端短漸尖，基部近圓形，稍偏斜，邊緣中部以上通常有鋸齒，幼時兩面被柔毛，後脫落；基部3出脈在下面明顯凸起。雄花在新枝下部排成聚傘花序，雌花1-3朵生於枝上部葉腋間。核果近球形，直徑約5mm；果梗長約1cm。花期3-4月；果期9-10月。','氹仔區飛能便度街','/photos/trees/601.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1782123.jpg',1,123,12.0,'一般','三級'),
('665',37,107,'聖方濟各堂區','三級',118,17.0,'一般',22.126075,113.556506,'official','665','T0023451','af705901-bc58-11ca-8000-94f1169f35c3',NULL,NULL,NULL,'常綠喬木。樹皮灰褐色，小枝褐色。葉薄革質，常集生枝頂，葉形及大小變化較大，常爲長圓形或長圓狀披針形，長12-30cm，寬3.5-6.5cm，邊緣皺波狀；葉柄長2-6cm，基部膨大。圓錐花序長20-35cm，多花密集，被灰黃色微柔毛；花小，雜性，錐花序長20-35cm，多花密集，被灰黃色微柔毛；花小，雜性，膨大，肉質，5淺裂；雄蕊僅1個發育；子房斜卵形，花柱近頂生。核果大，壓扁，成熟時黃色，中果皮肉質，肥厚，鮮黃色，果核堅硬。花期春季；果期夏季。','路環區石排灣郊野公園','/photos/trees/665.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1741526.jpg',1,118,17.0,'一般','三級'),
('329',50,57,'望德堂區','三級',115,30.0,'一般',22.201768,113.552323,'official','329','T0000385','98cebd9b-e0e9-4317-8271-63765482e2c4',6.0,71.0,223.1,'常綠喬木；樹皮紅褐色，裂成不規則的鱗狀塊片；枝條每年生長一輪，稀二輪，一年生枝淡黃褐色，無毛；冬芽圓柱形，褐色，芽鱗邊緣絲狀。針葉每束2針，稀3針，細柔，橫切面半圓形，皮下層細胞單型，有邊生。雄球花淡紅褐色，圓柱形，彎垂，聚生於新枝下部成穗狀，長6-15 cm；雌球花單生或2-4個聚生於新枝近頂端，淡紫紅色。一年生小毬果生於近枝頂；上部珠鱗的鱗臍具向上直伸的短剌，下部珠鱗的鱗臍平鈍無剌；毬果卵圓形，長4-7cm；鱗盾菱形，微隆起或平，鱗臍微凹，無剌；種子長卵圓形。','澳門區松山市政公園','/photos/trees/329.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004965.jpg',1,115,30.0,'一般','三級'),
('479',10,68,'花王堂區','三級',115,28.0,'一般',22.197759,113.540762,'official','479','T0000315','1a676cc7-a907-4ffd-a13a-2c10dfe8f3e8',NULL,74.0,232.5,'落葉大喬木，高可達25m以上；樹幹幼時有粗刺。掌狀複葉互生；葉柄稍長於小葉；小葉5-7片，長圓形至長圓狀披針形長10-20cm，寬3.5-7cm，頂端漸尖，基部闊楔形或漸窄，全緣，兩面無毛；小葉柄長約1.5-4cm。花紅色或橙紅色，直徑10-12cm，單生或聚生於近枝頂的葉腋；花萼杯狀，長2-4.5cm，內面被絹毛，3-5裂，裂片半圓形；花瓣帶肉質倒卵狀長圓形，長8-10cm，寬3-4cm，兩面多少有星狀細毛；雄蕊管短，花絲多數，外輪集成5組，與花瓣對生。蒴果長圓形，長10-15cm；種子藏於白色綿毛中。','澳門區白鴿巢公園','/photos/trees/479.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004892.jpg',1,115,28.0,'一般','三級'),
('222',36,88,'花地瑪堂區','三級',115,28.0,'一般',22.212339,113.535544,'official','222','T0000420','bf306775-37f7-4ebf-ac42-69f864e3eecc',NULL,NULL,NULL,'常綠喬木。葉革質，二型，生於幼樹或萌蘗枝上的葉盾形， 直徑約1 5 cm，掌狀3 - 5裂， 上面幾無毛，下面密被褐色星狀短柔毛；葉柄長約1 2 cm， 被毛， 生於成長樹上的葉長圓形至卵狀長圓形，頂端漸尖或鈍，基部斜圓形或斜心形， 長7-15cm，寬3-10cm，下面密被黃褐色短柔毛；葉柄長1-2cm。花單生或2-4朵組成腋生的聚傘花序；萼裂片條形，長約2.5cm，兩面均被柔毛；花瓣白色，倒披針形，與萼片等長；雌雄蕊柄長2.5cm，雄蕊15枚，每3個組成一組；子房卵圓形，被毛。蒴果木質，長圓狀卵形，長4-6cm，寬2-2.5cm，被黃褐色絨毛 ; 種子頂端具膜質翅。花期6-7月 ; 果期8-12月。','澳門區青洲山','/photos/trees/222.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004999.jpg',1,115,28.0,'一般','三級'),
('514',10,69,'望德堂區','三級',115,26.0,'一般',22.199575,113.548216,'official','514','T0000248','0d31ce81-719c-11c2-8000-d029ef855be3',NULL,98.0,307.9,'落葉大喬木，高可達25m以上；樹幹幼時有粗刺。掌狀複葉互生；葉柄稍長於小葉；小葉5-7片，長圓形至長圓狀披針形長10-20cm，寬3.5-7cm，頂端漸尖，基部闊楔形或漸窄，全緣，兩面無毛；小葉柄長約1.5-4cm。花紅色或橙紅色，直徑10-12cm，單生或聚生於近枝頂的葉腋；花萼杯狀，長2-4.5cm，內面被絹毛，3-5裂，裂片半圓形；花瓣帶肉質倒卵狀長圓形，長8-10cm，寬3-4cm，兩面多少有星狀細毛；雄蕊管短，花絲多數，外輪集成5組，與花瓣對生。蒴果長圓形，長10-15cm；種子藏於白色綿毛中。','澳門區盧廉若公園','/photos/trees/514.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004827.jpg',1,115,26.0,'一般','三級'),
('530',10,69,'望德堂區','三級',115,26.0,'一般',22.198946,113.547978,'official','530','T0000287','c55e4181-a465-11c8-8000-e9800050cec3',NULL,83.0,260.8,'落葉大喬木，高可達25m以上；樹幹幼時有粗刺。掌狀複葉互生；葉柄稍長於小葉；小葉5-7片，長圓形至長圓狀披針形長10-20cm，寬3.5-7cm，頂端漸尖，基部闊楔形或漸窄，全緣，兩面無毛；小葉柄長約1.5-4cm。花紅色或橙紅色，直徑10-12cm，單生或聚生於近枝頂的葉腋；花萼杯狀，長2-4.5cm，內面被絹毛，3-5裂，裂片半圓形；花瓣帶肉質倒卵狀長圓形，長8-10cm，寬3-4cm，兩面多少有星狀細毛；雄蕊管短，花絲多數，外輪集成5組，與花瓣對生。蒴果長圓形，長10-15cm；種子藏於白色綿毛中。','澳門區盧廉若公園','/photos/trees/530.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004866.jpg',1,115,26.0,'一般','三級'),
('782',10,25,'望德堂區','三級',115,26.0,'一般',22.20115,113.552502,'official','782','T0000291','776e3101-af6f-11c8-8000-059e04202463',NULL,74.0,232.5,'落葉大喬木，高可達25m以上；樹幹幼時有粗刺。掌狀複葉互生；葉柄稍長於小葉；小葉5-7片，長圓形至長圓狀披針形長10-20cm，寬3.5-7cm，頂端漸尖，基部闊楔形或漸窄，全緣，兩面無毛；小葉柄長約1.5-4cm。花紅色或橙紅色，直徑10-12cm，單生或聚生於近枝頂的葉腋；花萼杯狀，長2-4.5cm，內面被絹毛，3-5裂，裂片半圓形；花瓣帶肉質倒卵狀長圓形，長8-10cm，寬3-4cm，兩面多少有星狀細毛；雄蕊管短，花絲多數，外輪集成5組，與花瓣對生。蒴果長圓形，長10-15cm；種子藏於白色綿毛中。','澳門區二龍喉公園','/photos/trees/782.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004870.jpg',1,115,26.0,'一般','三級'),
('215',16,88,'花地瑪堂區','三級',115,25.0,'一般',22.213527,113.537589,'official','215','T0000439','a7c06699-de4e-4c2e-a5af-eb05679dc278',NULL,79.6,250.0,'常綠喬木；各部無毛，老樹常具鏽褐色氣根。葉薄革質，狹橢圓形，長4-8cm，寬3-4cm，全緣；托葉小，披針形。雌雄同株，榕果成對腋生或生於已落葉枝葉腋，熟時黃或微紅色，扁球形，徑6-8mm，無總柄，基生苞片3枚，廣卵形，宿存；榕果內花間有少許短剛毛，雄花無柄或具柄，散生內壁，花絲與花藥等長；雌花和癭花相似，花被片3枚，廣卵形，花柱近側生，柱頭短，棒形。瘦果卵圓形。花果期5-12月。','澳門區青洲山','/photos/trees/215.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005018.jpg',1,115,25.0,'一般','三級'),
('211',21,88,'花地瑪堂區','三級',115,21.0,'一般',22.210993,113.53611,'official','211','T0000434','b32a2eaa-8c3b-4fcf-936c-8e883b9cdcec',NULL,38.2,120.0,'喬木，高達15m；嫩枝圓形，乾後灰白色。葉革質，寬或狹橢圓形，長6-12cm，寬3.5-7cm，頂端圓或鈍，有短尖頭，基部寬楔形，稀近圓形，葉面乾後褐色或黑褐色，背面色稍淺，具密小腺點；側脈多而密；葉柄長1-2cm。花3-5朵排成聚傘花序，並再組成圓錐花序狀的聚傘花序，此花序長可達11cm；花梗極短，花萼筒短小，漏斗形，花萼齒小；花瓣4，小，白色；雄蕊短。漿果，卵球形或壺形，直徑1-2cm，熟時有宿存萼齒；種子1枚。花期2-3月。','澳門區青洲山','/photos/trees/211.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005013.jpg',1,115,21.0,'一般','三級'),
('252',21,88,'花地瑪堂區','三級',115,20.5,'一般',22.211183,113.539367,'official','252','T0000412','36129194-6440-4021-9538-249011742f3c',NULL,102.2,321.0,'喬木，高達15m；嫩枝圓形，乾後灰白色。葉革質，寬或狹橢圓形，長6-12cm，寬3.5-7cm，頂端圓或鈍，有短尖頭，基部寬楔形，稀近圓形，葉面乾後褐色或黑褐色，背面色稍淺，具密小腺點；側脈多而密；葉柄長1-2cm。花3-5朵排成聚傘花序，並再組成圓錐花序狀的聚傘花序，此花序長可達11cm；花梗極短，花萼筒短小，漏斗形，花萼齒小；花瓣4，小，白色；雄蕊短。漿果，卵球形或壺形，直徑1-2cm，熟時有宿存萼齒；種子1枚。花期2-3月。','澳門區青洲山','/photos/trees/252.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004992.jpg',1,115,20.5,'一般','三級'),
('353',18,57,'望德堂區','三級',115,20.0,'一般',22.199229,113.555206,'official','353','T0000375','0d963fca-866e-4803-a3c2-95f19c61790f',10.0,68.0,213.6,'喬木，高10-25m，胸徑可達150cm。小枝髓部周圍有柱狀維管束。芽時具托葉。小葉3-6對，紙質至革質，披針形或橢圓形至卵形，長6-14cm，寬2-5.5cm；頂端漸尖；基部楔形至圓形，偏斜，全緣。花序腋生；雄花序爲聚傘圓錐花序，長15-30cm，多花；雌花序爲總狀，長3-6cm，具花12朵以下。花萼長2.5-3mm，在雄花上具3淺齒，在雌花上近截平；雄蕊6枚，花絲合生1/2以上(在雌花中幾全長合生)；花盤在雄花中球形至圓柱形；在雌花中環狀，略具3波狀齒；雌蕊密被短柔毛，在雄花中退化。果序長1.5-15cm，具1-6果 ; 果卵圓形至紡錘形 ; 外果皮厚，乾有皺紋。花期4-5月 ; 果期10-12月。','澳門區松山市政公園','/photos/trees/353.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004955.jpg',1,115,20.0,'一般','三級'),
('354',19,57,'望德堂區','三級',115,20.0,'一般',22.199301,113.551084,'official','354','T0000356','c6982310-b181-435f-9869-242762f63b68',9.0,88.0,276.5,'喬木，高可達15m；樹皮厚，灰褐色，不開裂，分枝多。葉對生，薄革質，長圓形或橢圓形，長11-17 cm，寬4.5-7 cm，頂端急尖或漸尖，基部寬楔形或略圓，兩面多透明腺點；側脈9-13對，網脈明顯；葉柄長1-2cm。花無梗，2-3朵聚生，並排成圓錐花序狀的聚傘花序，花序着生在老枝上，長6-12cm；花萼筒半球形，花萼片合生成帽蓋狀，其頂端成短喙；雄蕊較花柱長。漿柱長。漿果，寬卵球形，直徑10-13mm。花期5-6月。','澳門區松山市政公園','/photos/trees/354.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004936.jpg',1,115,20.0,'一般','三級'),
('355',19,57,'望德堂區','三級',115,20.0,'一般',22.201915,113.554285,'official','355','T0000603','404ba81a-b884-4014-ad53-bed95ab8d9e0',8.0,94.0,295.3,'喬木，高可達15m；樹皮厚，灰褐色，不開裂，分枝多。葉對生，薄革質，長圓形或橢圓形，長11-17 cm，寬4.5-7 cm，頂端急尖或漸尖，基部寬楔形或略圓，兩面多透明腺點；側脈9-13對，網脈明顯；葉柄長1-2cm。花無梗，2-3朵聚生，並排成圓錐花序狀的聚傘花序，花序着生在老枝上，長6-12cm；花萼筒半球形，花萼片合生成帽蓋狀，其頂端成短喙；雄蕊較花柱長。漿柱長。漿果，寬卵球形，直徑10-13mm。花期5-6月。','澳門區松山市政公園','/photos/trees/355.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005190.jpg',1,115,20.0,'一般','三級'),
('521',9,69,'望德堂區','三級',115,20.0,'一般',22.19943,113.547414,'official','521','T0000278','3ccf9a81-a3ac-11c8-8000-e9800050cec3',NULL,225.0,706.9,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區盧廉若公園','/photos/trees/521.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004857.jpg',1,115,20.0,'一般','三級'),
('769',9,90,'花地瑪堂區','三級',115,20.0,'一般',22.203163,113.555696,'official','769','T0000041','bcaab6e9-cf1a-49ad-b6f9-ad805a3637bf',NULL,145.0,455.5,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區馬交石炮台馬路','/photos/trees/769.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004603.jpg',1,115,20.0,'一般','三級'),
('774',9,90,'花地瑪堂區','三級',115,20.0,'一般',22.203139,113.556116,'official','774','T0000192','b2be15a2-d41d-4d7a-bde5-3a099bcb844a',NULL,165.0,518.4,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區馬交石炮台馬路','/photos/trees/774.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004767.jpg',1,115,20.0,'一般','三級'),
('907',16,50,'花王堂區','三級',115,20.0,'一般',22.198332,113.542775,'official','907','T0000214','bad3955b-d185-474d-b802-4c95ec8c8fe4',NULL,158.0,496.4,'常綠喬木；各部無毛，老樹常具鏽褐色氣根。葉薄革質，狹橢圓形，長4-8cm，寬3-4cm，全緣；托葉小，披針形。雌雄同株，榕果成對腋生或生於已落葉枝葉腋，熟時黃或微紅色，扁球形，徑6-8mm，無總柄，基生苞片3枚，廣卵形，宿存；榕果內花間有少許短剛毛，雄花無柄或具柄，散生內壁，花絲與花藥等長；雌花和癭花相似，花被片3枚，廣卵形，花柱近側生，柱頭短，棒形。瘦果卵圓形。花果期5-12月。','澳門區新勝街','/photos/trees/907.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004789.jpg',1,115,20.0,'一般','三級'),
('948',9,81,'花地瑪堂區','三級',115,20.0,'一般',22.20837246,113.548643,'official','948','T0000014','43594f0a-db49-4711-8c9e-97676c6d18be',NULL,181.0,568.6,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區蓮峰街','/photos/trees/948.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004541.jpg',1,115,20.0,'一般','三級'),
('304',17,57,'望德堂區','三級',115,19.0,'一般',22.201573,113.553429,'official','304','T0000374','06139edb-72fd-4940-8280-c3d1fb033ea7',8.0,95.0,298.5,'常綠大喬木；高10-20(-30)m，胸徑達1-3m，樹冠大；具樟腦香氣；小枝無毛。葉薄革質，互生，卵狀橢圓形或長卵形，長6-12cm，寬2.5-6.5cm，頂端急尖，基部寬楔形至近圓形，邊緣多少波狀，葉面深綠色或黃綠色，有光澤，背面無毛或初時微被短柔毛；離基三出脈，側脈每邊2-5條，中脈在葉兩面均明顯，側脈在葉面上稍凸起，背面脈腋具明顯腺窩，窩內有短柔毛；葉柄長2-3cm。花多朵，排成圓錐花序狀的聚傘花序，花序長3.5-7cm，無毛或初時微被短柔毛；花黃白色或黃綠色，長約3mm，花被筒漏斗狀，花被裂片橢圓形，長約2mm，外面初時微被短柔毛，後脫落，內面密被短柔毛；子房近圓形，花柱短，柱頭頭狀。果近球形或卵球形，直徑6-8mm，熟時紫黑色，基部爲增大成淺杯狀或碟狀的果托所承托，果托邊緣全緣。花期4-5月；果期8-11月。','澳門區松山市政公園','/photos/trees/304.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/837162.jpg',1,115,19.0,'一般','三級'),
('423',9,43,'風順堂區','三級',115,19.0,'一般',22.182791,113.530546,'official','423','T0000218','1fec5ff8-2094-4864-b005-4e52f67ab709',NULL,220.0,691.2,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區媽閣上街','/photos/trees/423.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004793.jpg',1,115,19.0,'一般','三級'),
('61',16,124,'聖方濟各堂區','三級',115,19.0,'一般',22.11879368,113.5672188,'official','61','T0000561','35e314fb-bf3f-454a-bbf6-04143d1483c1',NULL,NULL,NULL,'常綠喬木；各部無毛，老樹常具鏽褐色氣根。葉薄革質，狹橢圓形，長4-8cm，寬3-4cm，全緣；托葉小，披針形。雌雄同株，榕果成對腋生或生於已落葉枝葉腋，熟時黃或微紅色，扁球形，徑6-8mm，無總柄，基生苞片3枚，廣卵形，宿存；榕果內花間有少許短剛毛，雄花無柄或具柄，散生內壁，花絲與花藥等長；雌花和癭花相似，花被片3枚，廣卵形，花柱近側生，柱頭短，棒形。瘦果卵圓形。花果期5-12月。','路環區黑沙村','/photos/trees/61.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005143.jpg',1,115,19.0,'一般','三級'),
('250',21,88,'花地瑪堂區','三級',115,18.6,'一般',22.213721,113.536483,'official','250','T0000427','10731d76-4ac7-49e3-8e40-78eb8d310054',NULL,58.3,183.0,'喬木，高達15m；嫩枝圓形，乾後灰白色。葉革質，寬或狹橢圓形，長6-12cm，寬3.5-7cm，頂端圓或鈍，有短尖頭，基部寬楔形，稀近圓形，葉面乾後褐色或黑褐色，背面色稍淺，具密小腺點；側脈多而密；葉柄長1-2cm。花3-5朵排成聚傘花序，並再組成圓錐花序狀的聚傘花序，此花序長可達11cm；花梗極短，花萼筒短小，漏斗形，花萼齒小；花瓣4，小，白色；雄蕊短。漿果，卵球形或壺形，直徑1-2cm，熟時有宿存萼齒；種子1枚。花期2-3月。','澳門區青洲山','/photos/trees/250.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005006.jpg',1,115,18.6,'一般','三級'),
('713',9,40,'花王堂區','三級',115,18.0,'一般',22.196394,113.543362,'official','713','T0000113','85a14fca-8a27-4a33-9a48-d468d7270107',NULL,134.5,422.5,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區大炮台公園','/photos/trees/713.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004682.jpg',1,115,18.0,'一般','三級'),
('716',9,40,'花王堂區','三級',115,18.0,'一般',22.197132,113.543077,'official','716','T0000117','07832f10-9df4-4840-9de6-dab7c7650dfd',NULL,134.5,422.5,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區大炮台公園','/photos/trees/716.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004686.jpg',1,115,18.0,'一般','三級'),
