('1039',9,58,'風順堂區','三級',115,10.0,'一般',22.184135,113.538042,'official','1039','T0000060','e486a2bb-373c-4261-8e73-7e248e4c08df',NULL,72.0,226.2,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區民國大馬路','/photos/trees/1039.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/869864.jpg',1,115,10.0,'一般','三級');
insert into public.trees (tree_no,species_id,site_id,parish_code,grade,age_years,height_m,health,lat,lon,geo_precision,official_no,iam_tree_no,ref_id,crown_m,diameter_cm,surround_m,official_description,official_loc,photo_url,photo_source,photo_count,official_age_years,official_height_m,official_health,official_grade) values
('507',34,65,'花王堂區','三級',115,10.0,'一般',22.200923,113.541177,'official','507','T0000466','476c3f18-a6f1-4ae5-8db8-3f03b59f075c',NULL,40.0,125.7,'常綠喬木；小枝密被黑色軟毛或無；頂芽卵圓形，芽鱗頂端長漸尖。葉螺旋狀着生，革質，線狀披針形，微彎，長7-15cm，寬0.7-1cm，上部微漸窄，頂端尖，基部楔形，上面深綠色；中脈顯著隆起，下面灰綠色，被白粉。雄球花穗狀，常2-5簇生，長3-5cm；雌球花單生稀成對，具梗。種子卵圓形或近球形，徑約1cm，成熟時假種皮紫黑色，被白粉，肉質種托柱狀橢圓形，紅或紫紅色。','澳門區澳門基督教聖堂及墳場','/photos/trees/507.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005049.jpg',1,115,10.0,'一般','三級'),
('909',41,74,'大堂區','三級',115,10.0,'一般',22.1950406143962,113.5441010631248,'official','909','T0034383','b93299b0-462e-43e5-ae04-8f3bac7d0bbf',NULL,69.0,216.8,'喬木；小枝初時疏生星狀柔毛。葉薄革質，橢圓形或長圓形，長8-25cm，寬5-15cm，頂端短尖或鈍，基部圓鈍，兩面均無毛；葉柄長2-5cm。圓錐花序頂生或腋生，下垂，長8-25cm；萼5裂至中部，裂片長條狀披針形；雄蕊柄彎曲，花藥黃色；雌花數較少，略大；子房圓球形，具柄，有溝紋5條，密被毛，花柱彎曲，柱頭5淺裂。蓇葖果紅色，厚革質，長圓狀卵形，長4-8cm，寬2-3.5cm，被短絨毛；種子黑褐色，橢圓狀球形，直徑約1.5cm。花期4-5月；果期8-9月。','澳門區聖公會聖馬可堂','/photos/trees/909.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1847998.jpg',1,115,10.0,'一般','三級'),
('738',9,104,'聖方濟各堂區','三級',115,10.0,'一般',22.119434,113.550716,'official','738','T0000542','21656b4b-e049-4543-9fa7-7d30e221c2cb',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區澳門保安部隊高等學校','/photos/trees/738.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005124.jpg',1,115,10.0,'一般','三級'),
('34',9,123,'聖方濟各堂區','三級',115,10.0,'一般',22.134107,113.58227,'official','34','T0034452','884ced2a-4850-434c-824b-29820a0bf154',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區鮑思高青年村','/photos/trees/34.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1708137.jpg',1,115,10.0,'一般','三級'),
('965',56,44,'風順堂區','三級',115,9.0,'一般',22.185928,113.531281,'official','965','T0000515','25d1f8dc-a91d-442a-a8cf-647b142f63d2',NULL,NULL,NULL,'常綠喬木，高達10m；小枝粗壯，被微柔毛，散生蒼白色皮孔。複葉連柄長15-30cm；小葉4-5對，薄革質，長圓狀橢圓形至長圓狀披針形，長6-15cm，寬2.5-5cm，基部極不對稱；小葉柄長不及5mm。花序大型，多分枝，頂生和近枝頂腋生，密被星狀毛；萼片近革質，覆瓦狀排列，兩面均被褐黃色絨毛和成束的星狀毛；花瓣乳白色；花絲被短硬毛。果近球形，黃褐色或灰黃色，外面稍粗糙。花期春夏間；果期夏季。','澳門區媽閣廟前地','/photos/trees/965.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005097.jpg',1,115,9.0,'一般','三級'),
('999',9,58,'風順堂區','三級',115,9.0,'一般',22.188361,113.532858,'official','999','T0000107','e97b4513-e4ed-468d-93e8-cde784050afc',NULL,121.0,380.1,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區民國大馬路','/photos/trees/999.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004676.jpg',1,115,9.0,'一般','三級'),
