('7',56,96,'聖方濟各堂區','三級',115,12.0,'健康',22.13229,113.589833,'official','7','T0000581','bbd20e6f-023e-49fd-9dd7-81a0a8d9fd25',NULL,68.44,215.0,'常綠喬木，高達10m；小枝粗壯，被微柔毛，散生蒼白色皮孔。複葉連柄長15-30cm；小葉4-5對，薄革質，長圓狀橢圓形至長圓狀披針形，長6-15cm，寬2.5-5cm，基部極不對稱；小葉柄長不及5mm。花序大型，多分枝，頂生和近枝頂腋生，密被星狀毛；萼片近革質，覆瓦狀排列，兩面均被褐黃色絨毛和成束的星狀毛；花瓣乳白色；花絲被短硬毛。果近球形，黃褐色或灰黃色，外面稍粗糙。花期春夏間；果期夏季。','路環區九澳聖母馬路','/photos/trees/7.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005168.jpg',1,115,12.0,'健康','三級'),
('138',16,116,'聖方濟各堂區','三級',115,12.0,'健康',22.11426628,113.5503128,'official','138','T0000323','db45b401-336d-11c9-8000-892577645ee3',NULL,NULL,NULL,'常綠喬木；各部無毛，老樹常具鏽褐色氣根。葉薄革質，狹橢圓形，長4-8cm，寬3-4cm，全緣；托葉小，披針形。雌雄同株，榕果成對腋生或生於已落葉枝葉腋，熟時黃或微紅色，扁球形，徑6-8mm，無總柄，基生苞片3枚，廣卵形，宿存；榕果內花間有少許短剛毛，雄花無柄或具柄，散生內壁，花絲與花藥等長；雌花和癭花相似，花被片3枚，廣卵形，花柱近側生，柱頭短，棒形。瘦果卵圓形。花果期5-12月。','路環區譚公廟前地','/photos/trees/138.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1836336.jpg',1,115,12.0,'健康','三級'),
('28',9,123,'聖方濟各堂區','三級',115,12.0,'健康',22.134132,113.581851,'official','28','T0034461','62d48e02-26b5-444e-ba8e-7df21599aa85',NULL,147.0,461.8,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區鮑思高青年村','/photos/trees/28.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1782668.jpg',1,115,12.0,'健康','三級'),
('893',2,70,'風順堂區','三級',115,11.0,'健康',22.18723346,113.535683,'official','893','T0000402','692af450-b2e1-45ad-b4f0-d6aba0f4da29',NULL,NULL,NULL,'喬木，高6-10m。葉薄革質，長圓形或卵狀橢圓形，長6-19cm，寬2.5-4cm，側脈多而密，近平行，不很明顯。花通常單生葉腋；花梗長達2cm或更長；萼片6，外被鏽色短柔毛；花冠白色，長6-8mm，裂片6，卵形，長3-5mm，頂端有不規則的齒缺；雄蕊6枚；不育雄蕊花瓣狀。漿果褐色，卵心形、卵圓形或橢圓形，長4-8cm。花、果期4-6月。','澳門區竹室正街休憩區','/photos/trees/893.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004982.jpg',1,115,11.0,'健康','三級'),
('1003',9,58,'風順堂區','三級',115,11.0,'健康',22.186067,113.536237,'official','1003','T0000219','58650470-e804-4583-b621-4ee1c73853d0',NULL,128.0,402.1,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區民國大馬路','/photos/trees/1003.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004794.jpg',1,115,11.0,'健康','三級'),
('1016',9,58,'風順堂區','三級',115,10.0,'健康',22.185744,113.534759,'official','1016','T0000227','5e6eb717-55d6-4dc7-9d5f-5bea8c1396b1',NULL,68.0,213.6,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區民國大馬路','/photos/trees/1016.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004805.jpg',1,115,10.0,'健康','三級'),
('1017',9,58,'風順堂區','三級',115,10.0,'健康',22.186826,113.536841,'official','1017','T0000112','939ab0fb-0e96-4d4f-acc3-d4009a1bcd06',NULL,104.0,326.7,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區民國大馬路','/photos/trees/1017.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004681.jpg',1,115,10.0,'健康','三級'),
('1020',9,58,'風順堂區','三級',115,10.0,'健康',22.185826,113.537541,'official','1020','T0000020','9bf33be0-09d8-4213-a579-9f6d2e695d07',NULL,94.0,295.3,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區民國大馬路','/photos/trees/1020.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004581.jpg',1,115,10.0,'健康','三級'),
('57',25,118,'聖方濟各堂區','三級',115,10.0,'健康',22.125968,113.565746,'official','57','T0000608','9c3d6fd0-a3cd-4c5b-bd96-75d457c4fb65',NULL,NULL,NULL,'常綠喬木；枝及葉柄被鏽色短柔毛。葉革質，橢圓形或倒卵狀長圓形，長8-15cm，寬4-7cm，全緣，幼樹之葉常羽狀淺裂，葉背面被粉狀柔毛；托葉線形，早落。雌雄同株，花序單生葉腋，雄花序長1.5-2cm，徑1-1.5cm，總柄長2-4.5cm，花與盾形苞片混生於倒卵形或球形的花序托上；雄花花被片4裂；雄蕊1枚；雌花花被管狀。聚花果近球形，徑3-4cm，淺黃色至橙黃色，被褐色短柔毛，表面有乳頭狀突起，果柄長3-5cm，被柔毛。花期5-8月；果期6-8月。','路環區路環步行徑','/photos/trees/57.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005195.jpg',1,115,10.0,'健康','三級'),
('111',9,115,'聖方濟各堂區','三級',115,10.0,'健康',22.121515,113.552959,'official','111','T0000551','2519f88f-51e5-40cb-8b00-1d5b5d75a324',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區荔枝碗馬路','/photos/trees/111.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/809767.jpg',1,115,10.0,'健康','三級'),
('431',34,68,'花王堂區','三級',115,9.0,'健康',22.200585,113.536331,'official','431','T0000295','590e6381-bc06-11c8-8000-65df20910223',NULL,71.0,223.1,'常綠喬木；小枝密被黑色軟毛或無；頂芽卵圓形，芽鱗頂端長漸尖。葉螺旋狀着生，革質，線狀披針形，微彎，長7-15cm，寬0.7-1cm，上部微漸窄，頂端尖，基部楔形，上面深綠色；中脈顯著隆起，下面灰綠色，被白粉。雄球花穗狀，常2-5簇生，長3-5cm；雌球花單生稀成對，具梗。種子卵圓形或近球形，徑約1cm，成熟時假種皮紫黑色，被白粉，肉質種托柱狀橢圓形，紅或紫紅色。','澳門區白鴿巢公園','/photos/trees/431.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004874.jpg',1,115,9.0,'健康','三級'),
('1022',9,58,'風順堂區','三級',115,9.0,'健康',22.187459,113.536218,'official','1022','T0000134','c722329f-a22a-47be-8749-f141b8a6fb1d',NULL,86.5,271.7,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區民國大馬路','/photos/trees/1022.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004703.jpg',1,115,9.0,'健康','三級'),
('786',32,25,'望德堂區','三級',115,8.0,'健康',22.201339,113.552006,'official','786','T0000292','b0a99f81-af75-11c8-8000-059e04202463',NULL,46.0,144.5,'落葉喬木，高達5m；枝條粗壯，帶肉質，具豐富乳汁。葉厚紙質，橢圓形或窄長橢圓形，僅下面中脈邊緣被柔毛；中脈在上面凹陷，側脈30-40對，近水平橫出；葉柄被短柔毛。花冠稍淡紅色或紫紅色，花冠裂片淡紅、黃或白色，基部黃色，斜展。蓇葖果長圓形。花期3-9月；果期6-12月。','澳門區二龍喉公園','/photos/trees/786.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004871.jpg',1,115,8.0,'健康','三級'),
('829',54,36,'大堂區','三級',115,8.0,'健康',22.191773,113.54391,'official','829','T0000335','154bc481-5f71-11c9-8000-3b014a847002',NULL,58.0,182.2,'常綠灌木或小喬木，高4-10m；樹皮灰白色。葉革質，近圓形或廣卵形，直徑8-15cm，頂端突尖，基部心形，全緣或具不明顯細圓齒，上面綠色；葉脈7或9條；葉柄長3-8cm。花序頂生或腋生，常數花排列成聚傘花序，總花梗長4-5cm；花萼長1.5-2.5cm；花瓣黃色，倒卵形，長約4.5cm；雄蕊柱長約3cm，平滑無毛。蒴果卵圓形，長約2cm，被絨毛。花期6-8月。','澳門區加思欄花園','/photos/trees/829.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004911.jpg',1,115,8.0,'健康','三級'),
('899',13,86,'風順堂區','三級',115,8.0,'健康',22.188551,113.534485,'official','899','T0000526','b063a307-e1ab-4d71-85c8-ec632223cc92',NULL,68.0,213.6,'灌木或喬木。葉卵形或寬卵形，長5-15cm，寬5-12cm，邊緣鋸齒粗鈍，有時爲各種缺裂，上面無毛，下面脈腋有簇毛；葉柄長1.5-5.5cm，具柔毛；托葉披針形。雌雄異株，花序腋生或生於芽鱗腋內；雄花序下垂，長2-3.5cm，密被白色柔毛，雄花花被橢圓形，淡綠色；雌花花序長1-2cm，被毛，總柄長0.5-1cm，雌花無柄，花被倒卵形，無花柱，柱頭2裂，內側具乳頭狀突起。聚花果卵狀橢圓形，長1-2.5cm，熟時紅或暗紫色。花果期2-8月。','澳門區鄭家大屋','/photos/trees/899.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005108.jpg',1,115,8.0,'健康','三級'),
('100',9,98,'聖方濟各堂區','三級',115,7.01,'健康',22.11797617,113.5519892,'official','100','T0000092','56d68c64-e4cc-4b34-8c58-bdcf95e65d8c',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區恩尼斯總統前地','/photos/trees/100.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004657.jpg',1,115,7.01,'健康','三級'),
('785',47,25,'望德堂區','三級',115,7.0,'健康',22.200621,113.552188,'official','785','T0000293','a8f3f601-af89-11c8-8000-059e04202463',NULL,NULL,NULL,'落葉喬木，高達8m；枝條粗壯，帶肉質，具豐富乳汁，葉痕明顯。葉厚紙質，長圓狀倒披針形或長橢圓形，兩面無毛；中脈在上面凹陷，側脈30-40對；葉柄上面基部具腺體，無毛。花冠外在上面凹陷，側脈30-40對；葉柄上面基部具腺體，無毛。花冠外黃色，外面無毛，內面密被柔毛，喉部無鱗片。蓇葖果圓筒形。花期5-10月；果期7-12月。','澳門區二龍喉公園','/photos/trees/785.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004872.jpg',1,115,7.0,'健康','三級'),
('52',27,118,'聖方濟各堂區','三級',115,7.0,'健康',22.12579322,113.5654995,'official','52','T0000613','b4a208a4-89f6-4821-97b7-e7372395099f',NULL,NULL,NULL,'灌木。小枝幼時被褐色茸毛，後漸脫落。葉常聚生於枝頂，革質，卵形至披針形，長2-8cm，寬1.5-4cm，頂端鈍圓至漸尖，基部楔形，邊緣具鋸齒；葉柄長5-18mm。圓錐狀或總狀花序頂生，長4-6cm；總花梗和花梗被鏽色絨毛；花白色或淡紅色，直徑1-1.3cm；花瓣5，倒卵形或披針形，長5-7mm，寬4-5mm，頂端圓鈍，基部具柔毛；雄蕊15；花柱2-3，基部合生。果球形，紫黑色，直徑約5mm，具粗果柄。花期2-4月；果期7-8月。','路環區路環步行徑','/photos/trees/52.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/2708664.jpg',1,115,7.0,'健康','三級'),
('42',9,107,'聖方濟各堂區','三級',115,15.0,'瀕危',22.125581,113.55728,'official','42','T0000371','7e46c801-d60c-11ca-8000-29e0b9c38722',15.0,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區石排灣郊野公園','/photos/trees/42.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004951.jpg',1,115,15.0,'瀕危','三級'),
('18',16,96,'聖方濟各堂區','三級',115,12.0,'瀕危',22.131368,113.589241,'official','18','T0000071','7da61156-a196-49f7-b988-8939ae5a236d',NULL,NULL,NULL,'常綠喬木；各部無毛，老樹常具鏽褐色氣根。葉薄革質，狹橢圓形，長4-8cm，寬3-4cm，全緣；托葉小，披針形。雌雄同株，榕果成對腋生或生於已落葉枝葉腋，熟時黃或微紅色，扁球形，徑6-8mm，無總柄，基生苞片3枚，廣卵形，宿存；榕果內花間有少許短剛毛，雄花無柄或具柄，散生內壁，花絲與花藥等長；雌花和癭花相似，花被片3枚，廣卵形，花柱近側生，柱頭短，棒形。瘦果卵圓形。花果期5-12月。','路環區九澳聖母馬路','/photos/trees/18.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004636.jpg',1,115,12.0,'瀕危','三級'),
('279',17,57,'望德堂區','三級',115,8.0,'瀕危',22.19994,113.554752,'official','279','T0000480','575d33b8-1443-40cc-b910-5c8b897782dd',1.2,62.0,194.8,'常綠大喬木；高10-20(-30)m，胸徑達1-3m，樹冠大；具樟腦香氣；小枝無毛。葉薄革質，互生，卵狀橢圓形或長卵形，長6-12cm，寬2.5-6.5cm，頂端急尖，基部寬楔形至近圓形，邊緣多少波狀，葉面深綠色或黃綠色，有光澤，背面無毛或初時微被短柔毛；離基三出脈，側脈每邊2-5條，中脈在葉兩面均明顯，側脈在葉面上稍凸起，背面脈腋具明顯腺窩，窩內有短柔毛；葉柄長2-3cm。花多朵，排成圓錐花序狀的聚傘花序，花序長3.5-7cm，無毛或初時微被短柔毛；花黃白色或黃綠色，長約3mm，花被筒漏斗狀，花被裂片橢圓形，長約2mm，外面初時微被短柔毛，後脫落，內面密被短柔毛；子房近圓形，花柱短，柱頭頭狀。果近球形或卵球形，直徑6-8mm，熟時紫黑色，基部爲增大成淺杯狀或碟狀的果托所承托，果托邊緣全緣。花期4-5月；果期8-11月。','澳門區松山市政公園','/photos/trees/279.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/836734.jpg',1,115,8.0,'瀕危','三級'),
('966',9,43,'風順堂區','三級',115,3.5,'瀕危',22.182916,113.530209,'official','966','T0000529','d0300d30-7080-4765-ad67-c50bd77ad3f2',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','澳門區媽閣上街','/photos/trees/966.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005111.jpg',1,115,3.5,'瀕危','三級'),
('873',17,59,'望德堂區','三級',113,15.0,'一般',22.199651818508567,113.5497126636932,'official','873','T0034583','ee29ef3f-c31c-4fa1-9161-f6666d866f66',NULL,93.0,292.2,'常綠大喬木；高10-20(-30)m，胸徑達1-3m，樹冠大；具樟腦香氣；小枝無毛。葉薄革質，互生，卵狀橢圓形或長卵形，長6-12cm，寬2.5-6.5cm，頂端急尖，基部寬楔形至近圓形，邊緣多少波狀，葉面深綠色或黃綠色，有光澤，背面無毛或初時微被短柔毛；離基三出脈，側脈每邊2-5條，中脈在葉兩面均明顯，側脈在葉面上稍凸起，背面脈腋具明顯腺窩，窩內有短柔毛；葉柄長2-3cm。花多朵，排成圓錐花序狀的聚傘花序，花序長3.5-7cm，無毛或初時微被短柔毛；花黃白色或黃綠色，長約3mm，花被筒漏斗狀，花被裂片橢圓形，長約2mm，外面初時微被短柔毛，後脫落，內面密被短柔毛；子房近圓形，花柱短，柱頭頭狀。果近球形或卵球形，直徑6-8mm，熟時紫黑色，基部爲增大成淺杯狀或碟狀的果托所承托，果托邊緣全緣。花期4-5月；果期8-11月。','澳門區治安警察局交通廳','/photos/trees/873.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/300195.jpg',1,113,15.0,'一般','三級'),
('139',9,116,'聖方濟各堂區','三級',113,13.0,'一般',22.11416,113.550418,'official','139','T0005460','243bba82-4293-4669-864a-c4fc41926a0a',6.0,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區譚公廟前地','/photos/trees/139.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1836337.jpg',1,113,13.0,'一般','三級'),
('1133',10,127,'聖方濟各堂區','三級',107,15.0,'一般',22.122047515820476,113.57011959439589,'official','1133','T0094646','9ac6d76f-5ee9-432a-a043-bfedb59df7f8',NULL,NULL,NULL,'落葉大喬木，高可達25m以上；樹幹幼時有粗刺。掌狀複葉互生；葉柄稍長於小葉；小葉5-7片，長圓形至長圓狀披針形長10-20cm，寬3.5-7cm，頂端漸尖，基部闊楔形或漸窄，全緣，兩面無毛；小葉柄長約1.5-4cm。花紅色或橙紅色，直徑10-12cm，單生或聚生於近枝頂的葉腋；花萼杯狀，長2-4.5cm，內面被絹毛，3-5裂，裂片半圓形；花瓣帶肉質倒卵狀長圓形，長8-10cm，寬3-4cm，兩面多少有星狀細毛；雄蕊管短，花絲多數，外輪集成5組，與花瓣對生。蒴果長圓形，長10-15cm；種子藏於白色綿毛中。','路環區黑沙臨時綠化休憩空間','/photos/trees/1133.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1917413.jpg',1,107,15.0,'一般','三級'),
('68',9,120,'聖方濟各堂區','三級',106,12.0,'健康',22.115417,113.556505,'official','68','T0034470','d84b3584-6eba-49ae-b3dc-0607ac4da7f1',NULL,NULL,NULL,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','路環區金像農場','/photos/trees/68.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1655795.jpg',1,106,12.0,'健康','三級'),
('549',9,4,'嘉模堂區','三級',103,18.0,'一般',22.152988,113.558085,'official','549','T0003468','f58347c1-fd26-4463-ab0a-7b4f16318d27',NULL,239.0,750.8,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','氹仔區嘉路士米耶馬路','/photos/trees/549.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/308976.jpg',1,103,18.0,'一般','三級'),
('550',9,4,'嘉模堂區','三級',103,17.0,'一般',22.153113,113.557748,'official','550','T0004440','85bfc6e8-b635-4b30-a801-abf59d880ff0',NULL,208.0,653.5,'別名為假菩提樹。喬木，常附生。葉近革質，心形至卵狀心形，長6-13cm，寬6-11cm，兩面無毛，基生葉脈5出；葉柄長6-8cm，無毛；托葉1.2-2.5cm，落後痕迹明顯。雌雄同株，榕果成對腋生或簇生於已落葉枝葉腋，球形，徑1-1.5cm，幼時被黑色斑點，熟時紫黑色，基生苞片3枚，圓形；雄花極少數，散生，花被片3枚，雄蕊1枚；癭花及中性花被片3枚，披針形；雌花花被與癭花相似，子房卵圓形，光滑。瘦果薄被瘤體和黏液，花柱長，柱頭棒狀。花果期5-9月。','氹仔區嘉路士米耶馬路','/photos/trees/550.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1874856.jpg',1,103,17.0,'一般','三級'),
('67',40,7,'嘉模堂區','不分級',35,10.01,'健康',22.15915798,113.5451663,'official','67','T0000610','6de6498b-8f06-4732-aaab-4d9f4707300c',NULL,NULL,NULL,'喬木。高約8-11m，無毛。芽細小，無毛或有毛。葉倒卵狀長圓形長5-10cm，寬2-4cm，先端鈍，基部狹，革質；葉柄長約10mm。圓錐花序頂生，2-4聚集，在上部分枝，有花6-10朵；花白色，花梗長約3mm；花被裂片長橢圓形，外面被柔毛，內輪長約4mm，外輪較短； 第三輪雄蕊腺體幾無柄，退化雄蕊有毛，子房球形。果球形。花期11月。果期次年2月。','氹仔區小潭山2000環山徑','/photos/trees/67.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005197.jpg',1,35,10.01,'健康','不分級'),
('1131',26,31,'大堂區','不分級',33,14.0,'一般',22.19183121,113.5495909,'official','1131','T0000256','baa17381-3fa3-11c6-8000-0c2f4993c043',3.0,39.0,122.5,'常綠大喬木；幼枝及芽綠色，密被淡黃白色微柔毛。葉薄革質，橢圓形或披針狀橢圓形，長10-27cm，寬4-9.5cm，上面無毛，下面疏生微柔毛；葉柄長1.5-2cm，托葉痕幾達葉柄中部。花極香，白色；花被片10片，披針形，長3-4cm，寬0.3-0.5cm；藥隔伸出成短尖頭；雌蕊群被微柔毛。蓇葖果熟時紅色。花期4-9月；果熟期10-11月。','澳門區何賢公園','/photos/trees/1131.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1004835.jpg',1,33,14.0,'一般','不分級'),
('66',40,7,'嘉模堂區','不分級',25,9.01,'健康',22.159052,113.545271,'official','66','T0000611','318cd9a9-b106-41cb-bd55-974bc73470df',NULL,NULL,NULL,'喬木。高約8-11m，無毛。芽細小，無毛或有毛。葉倒卵狀長圓形長5-10cm，寬2-4cm，先端鈍，基部狹，革質；葉柄長約10mm。圓錐花序頂生，2-4聚集，在上部分枝，有花6-10朵；花白色，花梗長約3mm；花被裂片長橢圓形，外面被柔毛，內輪長約4mm，外輪較短； 第三輪雄蕊腺體幾無柄，退化雄蕊有毛，子房球形。果球形。花期11月。果期次年2月。','氹仔區小潭山2000環山徑','/photos/trees/66.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005198.jpg',1,25,9.01,'健康','不分級'),
('1132',40,7,'嘉模堂區','三級',14,6.01,'一般',22.159177,113.544934,'official','1132','T0000616','badb0372-ab1f-468e-9e2e-d7652c30c489',1.7,NULL,NULL,'喬木。高約8-11m，無毛。芽細小，無毛或有毛。葉倒卵狀長圓形長5-10cm，寬2-4cm，先端鈍，基部狹，革質；葉柄長約10mm。圓錐花序頂生，2-4聚集，在上部分枝，有花6-10朵；花白色，花梗長約3mm；花被裂片長橢圓形，外面被柔毛，內輪長約4mm，外輪較短； 第三輪雄蕊腺體幾無柄，退化雄蕊有毛，子房球形。果球形。花期11月。果期次年2月。','氹仔區小潭山2000環山徑','/photos/trees/1132.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/1005203.jpg',1,14,6.01,'一般','不分級'),
('1135',40,7,'嘉模堂區','不分級',6,3.5,'健康',22.159333,113.545413,'official','1135','T0102831','0e5afa1a-f7c7-41c0-aa69-d54a8adbd613',NULL,10.0,31.4,'喬木。高約8-11m，無毛。芽細小，無毛或有毛。葉倒卵狀長圓形長5-10cm，寬2-4cm，先端鈍，基部狹，革質；葉柄長約10mm。圓錐花序頂生，2-4聚集，在上部分枝，有花6-10朵；花白色，花梗長約3mm；花被裂片長橢圓形，外面被柔毛，內輪長約4mm，外輪較短； 第三輪雄蕊腺體幾無柄，退化雄蕊有毛，子房球形。果球形。花期11月。果期次年2月。','氹仔區小潭山2000環山徑','/photos/trees/1135.jpg','https://www.iam.gov.mo/nature/Content/OldTreesOnline/2648021.jpg',1,6,3.5,'健康','不分級');
insert into public.routes (code,name_zh,summary,parish_codes,site_names,species_focus,max_stops,sort_order,tips) values ('macau-heritage-core','路綫一：澳門半島歷史城區古樹徑','由白鴿巢公園出發，經大炮台、盧廉若公園、加思欄花園到媽閣廟前地，一次走完半島舊城區最集中的古樹群。',ARRAY['花王堂區', '望德堂區', '大堂區', '風順堂區']::text[],ARRAY['澳門區白鴿巢公園', '澳門區大炮台公園', '澳門區盧廉若公園', '澳門區加思欄花園', '澳門區何東圖書館', '澳門區媽閣廟前地', '澳門區媽閣上街', '澳門區亞婆井前地', '澳門區主教山小堂', '澳門區鄭家大屋', '澳門區崗頂劇院']::text[],'榕屬、海南蒲桃、鳳凰木',10,1,'全程步行，建議早上出發；公園開放時間內進入；勿踩踏樹根與攀爬樹幹。');
insert into public.routes (code,name_zh,summary,parish_codes,site_names,species_focus,max_stops,sort_order,tips) values ('macau-north-parks','路綫二：北區公園與山邊古樹徑','松山市政公園、二龍喉公園、螺絲山公園、望廈山市政公園與青洲山，觀察山體與泉水如何養活古樹。',ARRAY['花地瑪堂區', '望德堂區']::text[],ARRAY['澳門區松山市政公園', '澳門區二龍喉公園', '澳門區螺絲山公園', '澳門區望廈山市政公園', '澳門區青洲山', '澳門區觀音古廟', '澳門區普濟禪院（觀音堂）', '澳門區馬交石炮台馬路']::text[],'榕樹、樟樹、羅漢松',8,2,'松山路段有坡度，建議穿運動鞋；觀音古廟內有全澳最老古樹（515 年海南蒲桃）。');
insert into public.routes (code,name_zh,summary,parish_codes,site_names,species_focus,max_stops,sort_order,tips) values ('taipa-carmo','路綫三：氹仔嘉模與龍環葡韻古樹徑','嘉模斜巷、龍環葡韻一帶、益隆炮竹廠、小潭山環山徑，看葡式住宅與假菩提樹組成的地景。',ARRAY['嘉模堂區']::text[],ARRAY['氹仔區嘉模斜巷', '氹仔區關帝殿及天后宮', '氹仔區益隆炮竹廠', '氹仔區嘉路士米耶馬路', '氹仔區飛能便度街', '氹仔區菜園路', '氹仔區小潭山2000環山徑', '氹仔區徐日昇寅公馬路']::text[],'假菩提樹（心葉榕）、樟樹',8,3,'適合親子；龍環葡韻一帶有洗手間與飲水機；環山徑全程約 2 公里。');
insert into public.routes (code,name_zh,summary,parish_codes,site_names,species_focus,max_stops,sort_order,tips) values ('coloane-wild','路綫四：路環郊野與村落古樹徑','石排灣郊野公園、九澳聖母馬路、黑沙海灘公園、路環舊市區十月初五馬路——全澳古樹最密集的一條路綫。',ARRAY['聖方濟各堂區']::text[],ARRAY['路環區石排灣郊野公園', '路環區九澳聖母馬路', '路環區九澳村路', '路環區黑沙海灘公園', '路環區竹灣馬路', '路環區十月初五馬路', '路環區恩尼斯總統前地', '路環區船人街', '路環區石街', '路環區打纜街', '路環區鮑思高青年村', '路環區譚公廟前地']::text[],'假菩提樹（心葉榕）、龍眼、華潤楠',12,4,'建議乘巴士至石排灣起步；郊野路段注意防曬與補水；黑沙海灘可作終點。');
insert into public.routes (code,name_zh,summary,parish_codes,site_names,species_focus,max_stops,sort_order,tips) values ('oldest-trees','路綫五：全澳最老古樹巡禮','不按地區，只按樹齡——把全澳最老的十株古樹串成一條路綫，包括 515 年的海南蒲桃。','{}','{}','海南蒲桃、假菩提樹、樟樹',10,5,'此路綫橫跨半島與離島，建議分兩日；實際停靠點由系統按樹齡最高的個體自動選出。');
insert into public.conservation_topics (slug,category,title,summary,body_md,sources,sort_order) values ('why-conserve','為何保育','為什麼要保育「古樹」？對現在與將來的意義','古樹不只是老樹：它是城市裡唯一「活着」的歷史文物，同時提供降溫、固碳、滯塵與生物棲地等生態服務。','## 一、古樹是「不可複製」的文化遺產
insert into public.conservation_topics (slug,category,title,summary,body_md,sources,sort_order) values ('distribution','分佈與歷史','古樹在澳門的分佈（生物與地理角度）','古樹高度集中在舊城區的廟宇、教堂、花園，以及離島的郊野公園與村落——分佈由「歷史開發」與「物種生態需求」兩股力量共同決定。','## 一、地理角度：古樹住在哪裡？
insert into public.conservation_topics (slug,category,title,summary,body_md,sources,sort_order) values ('history-link','分佈與歷史','澳門歷史背景與現存古樹的關聯：為何在「那個時段」出現？','每一株古樹的樹齡都是一個歷史事件的回聲：開埠、明清廟宇建設、18–19 世紀花園宅邸、填海與馬路開闢，以及 1970 年代後的郊野保育。','## 一、用樹齡「回推」歷史時段
insert into public.conservation_topics (slug,category,title,summary,body_md,sources,sort_order) values ('conditions','管護技術','保育古樹需要什麼條件？','古樹存活的條件可分為「立地條件」、「技術條件」與「制度條件」三層，缺一不可。','## 一、立地條件（樹能不能活着）
insert into public.conservation_topics (slug,category,title,summary,body_md,sources,sort_order) values ('legislation','立法與制度','何時立法保護古樹？澳門古樹保護的制度史','2013 年《文化遺產保護法》把古樹名木寫進法律（2014 年生效），2016 年首次核准《古樹名木保護名錄》，此後多次更新至 2026 年。','## 一、時間線
insert into public.conservation_topics (slug,category,title,summary,body_md,sources,sort_order) values ('residents','居民與社區','古樹對附近居民的影響：正面與負面都要誠實面對','古樹同時是「公共財」與「風險源」：樹蔭、降溫、認同感是收益；板根破壞路面、枯枝墜落、落果與蚊患是成本。','## 一、正面影響
insert into public.conservation_topics (slug,category,title,summary,body_md,sources,sort_order) values ('future','管護技術','為何未來古樹會越來越多？又該如何應對？','「越來越多」不是自然會發生，而是三個機制疊加的結果：樹木持續跨過 100 年門檻、名錄持續擴充、城市綠化存量累積——前提是今天的新樹在 100 年後仍然存在。','## 一、為什麼未來會越來越多？三個機制
insert into public.conservation_topics (slug,category,title,summary,body_md,sources,sort_order) values ('stories','分佈與歷史','古樹與地方的故事','白鴿巢公園、觀音古廟、盧廉若公園、龍環葡韻、石排灣郊野公園、媽閣廟——每一處的名字背後，都有一株樹在記帳。','## 1. 觀音古廟（花地瑪堂區）——最老的一株
insert into public.conservation_topics (slug,category,title,summary,body_md,sources,sort_order) values ('math-analysis','數學與數據','數學角度：用統計模型分析樹齡、樹高與品種的關係','以 658 筆名錄資料作迴歸與變異數分析，結果出人意表：樹齡幾乎不能解釋樹高，品種才是主導因子——這個「失敗的擬合」本身就是重要發現。','## 一、變數與資料
insert into public.conservation_topics (slug,category,title,summary,body_md,sources,sort_order) values ('extras','常見問題','想補充的相關知識：古樹名木的專業常識','樹齡怎麼算？分級怎麼分？什麼是樹木風險評估、斷層檢測、生物力學與碳儲量？一次補齊。','## 1. 古樹名木的分級標準
insert into public.conservation_topics (slug,category,title,summary,body_md,sources,sort_order) values ('faq','常見問題','常見問題 FAQ','澳門有多少古樹？最老的是哪一株？可以移植嗎？遊客能做什麼？','**Q：澳門現在有多少古樹？**
insert into public.timeline_events (year,event_date,title,detail,source) values (1984,'1984','第 56/84/M 號法令','澳門首次系統保護「紀念物、建築群及場所」，建立受保護不動產概念，但未直接涵蓋樹木。','澳門政府公報第 27 期（1984-06-30）');
insert into public.timeline_events (year,event_date,title,detail,source) values (1992,'1992','第 83/92/M 號法令','擴充受保護不動產清單，部分古樹所在的花園與廟宇建築群被納入。','澳門政府公報第 52 期第四副刊（1992-12-31）');
insert into public.timeline_events (year,event_date,title,detail,source) values (2013,'2013-09-02','第 11/2013 號法律《文化遺產保護法》刊登','第 106 條首次把「古樹名木」定義為文化遺產的一類，並要求以行政長官批示核准《古樹名木保護名錄》。','澳門特別行政區公報第 36 期第一組');
insert into public.timeline_events (year,event_date,title,detail,source) values (2014,'2014-03-01','《文化遺產保護法》生效','禁止拔除、砍伐、毀損及移植名錄內樹木；名錄樹木所有人負有維護與通報義務。','第 11/2013 號法律');
insert into public.timeline_events (year,event_date,title,detail,source) values (2016,'2016-10-05','首次核准《古樹名木保護名錄》','第 333/2016 號行政長官批示，澳門古樹保護由「原則」進入「點名」階段。','澳門特別行政區公報第 40 期第一組');
insert into public.timeline_events (year,event_date,title,detail,source) values (2020,'2020-06-15 / 2020-11-16','兩度更新名錄','第 130/2020 號及第 216/2020 號行政長官批示先後更新《古樹名木保護名錄》。','澳門特別行政區公報第 24、46 期第一組');
insert into public.timeline_events (year,event_date,title,detail,source) values (2021,'2021-11-08','再次更新名錄','第 168/2021 號行政長官批示更新名錄；市政署同期成立古樹小組，專責實地檢查、管護與保育。','澳門特別行政區公報第 45 期第一組');
insert into public.timeline_events (year,event_date,title,detail,source) values (2024,'2024-07-22','第 118/2024 號行政長官批示','核准新版《古樹名木保護名錄》；同年第 4/2024 號行政法規訂定「澳門歷史城區」保護及管理計劃。','澳門特別行政區公報第 30 期第一組');
insert into public.timeline_events (year,event_date,title,detail,source) values (2026,'2026-01-05','第 279/2025 號行政長官批示（現行名錄）','核准現行《古樹名木保護名錄》，廢止第 118/2024 號批示。市政署表示將持續與內地科研單位合作加強管護。','澳門特別行政區公報第 1 期第一組');
